def _date(value: str) -> date:
    try:
        return date.fromisoformat(value)
    except ValueError as error:
        raise argparse.ArgumentTypeError("дата должна быть YYYY-MM-DD") from error

async def _network_command(args: argparse.Namespace) -> None:
    service = args.pin_keychain_service
    account = args.pin_keychain_account
    if (service is None) != (account is None) or service == "" or account == "":
        raise ValueError(
            "--pin-keychain-service и --pin-keychain-account должны задаваться вместе"
        )
    if service is not None:
        client = await AsyncSberClient.from_pin_profile(
            args.session,
            pin=lambda: _read_keychain_pin(service, account),
        )
    else:
        client = AsyncSberClient.from_session_file(args.session)
    async with client:
        if args.command == "balances":
            result: Any = await client.products.get(force_update=args.force_update)
        else:
            result = await client.operations.list(
                resource=args.resource,
                from_=args.from_,
                to=args.to,
            )
        _write_private_json(args.output, result)
        if args.save_session:
            client.session.export(args.save_session)
    print(args.output)

def _read_deviceprint(path: Path) -> str:
    try:
        value = _read_session_file(path, require_private=True).decode("utf-8").rstrip("\r\n")
    except UnicodeError as error:
        raise ValueError("deviceprint-file должен быть UTF-8") from error
    if not value or len(value) > 64 * 1024 or any(ord(char) < 0x20 or ord(char) == 0x7F for char in value):
        raise ValueError("deviceprint-file содержит некорректное значение")
    return value

async def _interactive_pin_login(auth: AsyncPinAuth, args: argparse.Namespace) -> SessionBundle:
    captcha_code: str | None = None
    audio_captcha = False
    captcha_number = 0
    while True:
        pin = getpass.getpass("PIN СберБанк Онлайн: ")
        try:
            current_code, captcha_code = captcha_code, None
            if current_code is None:
                return await auth.login(pin)
            if audio_captcha:
                return await auth.login(pin, audio_captcha_code=current_code)
            return await auth.login(pin, captcha_code=current_code)
        except PinCaptchaRequired as challenge:
            captcha_number += 1
            captcha_code, audio_captcha = await _prompt_captcha(auth, challenge, args, captcha_number)
        except PinOtpRequired:
            bundle = await _interactive_otp(auth)
            assert bundle is not None   # AsyncPinAuth.confirm_otp always yields a session
            return bundle
        finally:
            pin = ""

