async def _interactive_otp(
    auth: AsyncPinAuth | AsyncPrimaryAuth,
    *,
    max_prompts: int = 5,
) -> SessionBundle | None:
    prompts = 0
    while prompts < max_prompts:
        prompts += 1
        code = getpass.getpass("SMS-код: ")
        try:
            return await auth.confirm_otp(code)
        except PinAuthError as error:
            # The primary flow reports remaining_attempts=None (unknown); treat that as
            # "keep trying" but bound the loop locally so a wrong code can't spin forever.
            if error.code == "wrong_code" and error.remaining_attempts != 0:
                if error.remaining_attempts is not None:
                    print(f"SMS-код неверен; осталось попыток: {error.remaining_attempts}")
                else:
                    print(f"SMS-код неверен; локальных попыток осталось: {max_prompts - prompts}")
                continue
            if error.code == "expired_code":
                answer = input("SMS-код истёк. Запросить новый? [y/N]: ").strip().lower()
                if answer in {"y", "yes", "д", "да"}:
                    challenge = await auth.retry_otp()
                    lifetime = challenge.lifetime if challenge.lifetime is not None else "неизвестно"
                    print(f"Новый SMS-код запрошен; срок: {lifetime} сек.")
                    continue
            raise
        finally:
            code = ""
    raise PinAuthError(
        "Исчерпан лимит локальных попыток ввода SMS-кода",
        code="local_attempts_exhausted",
    )

def _captcha_path(requested: Path | None, number: int, suffix: str) -> Path:
    if requested is None:
        return _temporary_captcha_path(suffix)
    if number == 1:
        return requested
    return requested.with_name(f"{requested.stem}-{number}{requested.suffix or suffix}")

def main() -> None:
    parser = _parser()
    args = parser.parse_args()
    # Create output parents up front: a missing directory otherwise surfaces only in
    # the final save(), after enrollment/PIN creation has already run and cannot repeat.
    for attr in ("output", "save_session", "captcha_output"):
        target = getattr(args, attr, None)
        if target is not None:
            target.parent.mkdir(parents=True, exist_ok=True)
    try:
        if args.command == "import-session":
            bundle = SessionBundle.from_files(args.har, args.cookies)
            bundle.save(args.output)
            print(json.dumps({
                "output": str(args.output),
                "cookie_count": len(bundle.cookies),
                "api_base": bundle.api_base,
                "web_base": bundle.web_base,
            }, ensure_ascii=False, indent=2))
        elif args.command == "inspect-session":
            print(json.dumps(SessionBundle.load(args.session).redacted(), ensure_ascii=False, indent=2))
        elif args.command == "pin-login":
            asyncio.run(_pin_login_command(args))
        elif args.command == "enroll":
            asyncio.run(_enroll_command(args))
        else:
            asyncio.run(_network_command(args))
    except (SberError, OSError, ValueError, EOFError, KeyboardInterrupt) as error:
        parser.exit(2, f"error: {error}\n")

def _host_allowed(host: str | None) -> bool:
    host = (host or "").lower().rstrip(".")
    return host == "sberbank.ru" or host.endswith(".sberbank.ru")

def _online_url(value: str) -> bool:
    try:
        parsed = urlsplit(value)
        port = parsed.port
    except ValueError:
        return False
    host = (parsed.hostname or "").lower()
    return not parsed.username and not parsed.password and port in (None, 443) and parsed.scheme == "https" and (
        host == "online.sberbank.ru" or host.endswith(".online.sberbank.ru")
    )

def _headers(items: Any) -> dict[str, str]:
    result: dict[str, str] = {}
    if not isinstance(items, list):
        return result
    for item in items:
        if not isinstance(item, Mapping):
            continue
        name = str(item.get("name", "")).lower()
        value = item.get("value")
        if name and isinstance(value, str) and "\r" not in value and "\n" not in value:
            result[name] = value
    return result

def _default_cookie_path(request_path: str) -> str:
    if not request_path.startswith("/") or request_path.count("/") <= 1:
        return "/"
    return request_path.rsplit("/", 1)[0] or "/"

