def _timestamp(value: Any) -> int | None:
    if isinstance(value, (int, float)):
        return int(value)
    if not isinstance(value, str) or not value:
        return None
    try:
        return int(datetime.fromisoformat(value.replace("Z", "+00:00")).timestamp())
    except ValueError:
        try:
            return int(parsedate_to_datetime(value).timestamp())
        except (TypeError, ValueError, OverflowError):
            return None

def _structured_cookies(
    items: Any,
    fallback_host: str,
    default_path: str = "/",
    received_at: int | None = None,
) -> list[Cookie]:
    result: list[Cookie] = []
    if not isinstance(items, list):
        return result
    for item in items:
        if not isinstance(item, Mapping):
            continue
        expires = _timestamp(item.get("expires"))
        max_age = item.get("maxAge", item.get("max-age"))
        try:
            if max_age is not None:
                expires = (received_at or int(clock.time())) + int(max_age)
        except (TypeError, ValueError):
            pass
        cookie = _cookie(
            str(item.get("name", "")),
            str(item.get("value", "")),
            str(item.get("domain") or fallback_host),
            str(item.get("path") or default_path),
            secure=bool(item.get("secure", True)),
            http_only=bool(item.get("httpOnly", False)),
            domain_specified=bool(item.get("domain")) and not bool(item.get("hostOnly", False)),
            expires=expires,
            origin_host=fallback_host,
        )
        if cookie:
            result.append(cookie)
    return result

def _cookie_header(value: str, fallback_host: str) -> list[Cookie]:
    parsed = SimpleCookie()
    try:
        parsed.load(value)
    except Exception:
        return []
    result = []
    for name, morsel in parsed.items():
        cookie = _cookie(
            name,
            morsel.value,
            fallback_host,
            domain_specified=False,
            origin_host=fallback_host,
        )
        if cookie:
            result.append(cookie)
    return result

def _set_cookie_header(
    value: str,
    fallback_host: str,
    request_path: str = "/",
    received_at: int | None = None,
) -> list[Cookie]:
    parsed = SimpleCookie()
    try:
        parsed.load(value)
    except Exception:
        return []
    result = []
    for name, morsel in parsed.items():
        expires = _timestamp(morsel["expires"])
        if morsel["max-age"]:
            try:
                expires = (received_at or int(clock.time())) + int(morsel["max-age"])
            except ValueError:
                pass
        cookie = _cookie(
            name,
            morsel.value,
            morsel["domain"] or fallback_host,
            morsel["path"] or _default_cookie_path(request_path),
            secure=bool(morsel["secure"]),
            http_only=bool(morsel["httponly"]),
            domain_specified=bool(morsel["domain"]),
            expires=expires,
            origin_host=fallback_host,
        )
        if cookie:
            result.append(cookie)
    return result

def _clear_cookie(jar: CookieJar, cookie: Cookie) -> None:
    target_domain = cookie.domain.lstrip(".").lower()
    for existing in list(jar):
        if (
            existing.name == cookie.name
            and existing.path == cookie.path
            and existing.domain.lstrip(".").lower() == target_domain
        ):
            jar.clear(existing.domain, existing.path, existing.name)

def _apply_cookie(jar: CookieJar, cookie: Cookie) -> None:
    if cookie.expires is not None and cookie.expires <= int(clock.time()):
        _clear_cookie(jar, cookie)
    else:
        jar.set_cookie(cookie)

def _private_file(path: Path) -> bool:
    mode = path.lstat().st_mode
    return stat.S_ISREG(mode) and stat.S_IMODE(mode) & 0o077 == 0

def load_netscape_cookies(path: Path, *, require_private: bool = True) -> CookieJar:
    """Load a cookies.txt export while retaining RFC domain/path/expiry metadata."""
    if not path.exists() or not path.is_file():
        raise MissingSession(f"cookie-файл не найден: {path}")
    if require_private and not _private_file(path):
        raise InsecureSessionFile(f"cookie-файл доступен другим пользователям; выполните: chmod 600 {path}")

    jar = CookieJar()
    with path.open(encoding="utf-8-sig") as file:
        for line_number, line in enumerate(file, 1):
            raw = line.rstrip("\r\n")
            if not raw:
                continue
            http_only = raw.startswith("#HttpOnly_")
            if http_only:
                raw = raw.removeprefix("#HttpOnly_")
            elif raw.lstrip().startswith("#"):
                continue
            columns = raw.split("\t", 6)
            if len(columns) != 7:
                raise MissingSession(f"cookies.txt: неверная строка {line_number}")
            domain, include_subdomains, cookie_path, secure, raw_expires, name, value = columns
            if include_subdomains.upper() not in {"TRUE", "FALSE"} or secure.upper() not in {"TRUE", "FALSE"}:
                raise MissingSession(f"cookies.txt: неверные флаги в строке {line_number}")
            if not cookie_path.startswith("/") or any(ord(char) < 0x20 or ord(char) == 0x7F for char in cookie_path):
                raise MissingSession(f"cookies.txt: неверный path в строке {line_number}")
            try:
                expires_value = int(raw_expires)
            except ValueError as error:
                raise MissingSession(f"cookies.txt: неверный expiry в строке {line_number}") from error
            cookie = _cookie(
                name,
                value,
                domain,
                cookie_path or "/",
                secure=secure.upper() == "TRUE",
                http_only=http_only,
                domain_specified=include_subdomains.upper() == "TRUE" or domain.startswith("."),
                expires=expires_value if expires_value > 0 else None,
                origin_host=domain.lstrip("."),
            )
            if cookie:
                _apply_cookie(jar, cookie)
    jar.clear_expired_cookies()
    if not any(True for _ in jar):
        raise MissingSession("cookie-файл не содержит действующих cookies СберБанк Онлайн")
    return jar

def _merge_cookies(target: CookieJar, source: CookieJar) -> None:
    for cookie in source:
        _apply_cookie(target, cookie)

def _session_cookies_ready(jar: CookieJar, api_base: str | None, web_base: str | None) -> bool:
    if not api_base or not web_base:
        return False
    return all(
        _jar_sends_cookie(jar, url)
        for url in (
            f"{web_base.rstrip('/')}{WARMUP_PATH}",
            f"{api_base.rstrip('/')}{PRODUCTS_PATH}",
            f"{api_base.rstrip('/')}{OPERATIONS_PATH}",
        )
    )

def _runtime_online_origin(text: str, key: str) -> str | None:
    occurrences = len(re.findall(rf'"{re.escape(key)}"\s*:', text))
    literals = re.findall(
        rf'"{re.escape(key)}"\s*:\s*("(?:\\.|[^"\\])*")',
        text,
    )
    if not literals or len(literals) != occurrences:
        return None
    values: set[str] = set()
    for literal in literals:
        try:
            value = json.loads(literal)
            parsed = urlsplit(value)
        except (json.JSONDecodeError, TypeError, ValueError):
            return None
        if (
            not isinstance(value, str)
            or not _online_url(value)
            or parsed.path not in ("", "/")
            or parsed.query
            or parsed.fragment
        ):
            return None
        values.add(value.rstrip("/"))
    return values.pop() if len(values) == 1 else None

def _ufs_host_from_app_shell(text: str) -> str | None:
    """Extract the frontend ``ufsHost`` from the public ``/app/main`` shell."""
    return _runtime_online_origin(text, "ufsHost")

def _api_base_from_main_html(text: str) -> str | None:
    """Extract the runtime UFS root from an already fetched ``/main`` page."""
    return _runtime_online_origin(text, "ufs.block.root.url")

def _main_config_base(entry: Mapping[str, Any]) -> str | None:
    request = entry.get("request")
    response = entry.get("response")
    if not isinstance(request, Mapping) or not isinstance(response, Mapping):
        return None
    url = str(request.get("url", ""))
    parsed = urlsplit(url)
    if parsed.path != "/main" or not _online_url(url):
        return None
    content = response.get("content")
    text = content.get("text") if isinstance(content, Mapping) else None
    if not isinstance(text, str):
        return None
    return _api_base_from_main_html(text)

def inspect_har(path: Path) -> tuple[HarInspection, CookieJar]:
    with path.open(encoding="utf-8") as file:
        har = json.load(file)
    entries = har.get("log", {}).get("entries", []) if isinstance(har, Mapping) else []
    if not isinstance(entries, list):
        raise MissingSession("HAR log.entries отсутствует")

    api_bases: list[str] = []
    web_bases: list[str] = []
    observed_headers: dict[str, str] = {}
    antifraud_deviceprint: str | None = None
    target_request_count = 0
    jar = CookieJar()

    for entry in entries:
        if not isinstance(entry, Mapping):
            continue
        request = entry.get("request")
        response = entry.get("response")
        if not isinstance(request, Mapping):
            continue
        url = str(request.get("url", ""))
        if not _online_url(url):
            continue
        parsed = urlsplit(url)
        host = parsed.hostname or ""
        received_at = _entry_timestamp(entry)
        request_headers = _headers(request.get("headers"))
        captured_antifraud = request_headers.get("rsa-antifraud-device-print")
        is_observed_mutation = (
            str(request.get("method", "")).upper() == "POST"
            and parsed.path in MUTATION_PATHS
        )
        if captured_antifraud and is_observed_mutation:
            if len(captured_antifraud) > 64 * 1024 or any(
                ord(char) < 0x20 or ord(char) == 0x7F for char in captured_antifraud
            ):
                raise MissingSession("HAR содержит некорректный antifraud deviceprint")
            antifraud_deviceprint = captured_antifraud

        if parsed.path in READ_PATHS:
            target_request_count += 1
            api_bases.append(f"{parsed.scheme}://{parsed.netloc}")
            for name, value in request_headers.items():
                if name in OBSERVED_HEADER_NAMES:
                    observed_headers[name] = value
        if parsed.path == "/main" and re.fullmatch(r"web\d+\.online\.sberbank\.ru", host):
            web_bases.append(f"{parsed.scheme}://{parsed.netloc}")
        configured = _main_config_base(entry)
        if configured:
            api_bases.append(configured)

        cookies = _structured_cookies(request.get("cookies"), host, received_at=received_at)
        if not cookies and "cookie" in request_headers:
            cookies = _cookie_header(request_headers["cookie"], host)
        for cookie in cookies:
            _apply_cookie(jar, cookie)

        if isinstance(response, Mapping):
            response_cookies = _structured_cookies(
                response.get("cookies"),
                host,
                _default_cookie_path(parsed.path),
                received_at,
            )
            for header in response.get("headers", []) if isinstance(response.get("headers"), list) else []:
                if isinstance(header, Mapping) and str(header.get("name", "")).lower() == "set-cookie":
                    response_cookies.extend(
                        _set_cookie_header(
                            str(header.get("value", "")),
                            host,
                            parsed.path,
                            received_at,
                        )
                    )
            for cookie in response_cookies:
                _apply_cookie(jar, cookie)

    api_base = api_bases[-1] if api_bases else None
    web_base = web_bases[-1] if web_bases else None
    jar.clear_expired_cookies()
    cookie_count = sum(1 for _ in jar)
    return (
        HarInspection(
            api_base=api_base,
            web_base=web_base,
            cookie_count=cookie_count,
            has_sensitive_session=_session_cookies_ready(jar, api_base, web_base),
            target_request_count=target_request_count,
            observed_headers=observed_headers,
            antifraud_deviceprint=antifraud_deviceprint,
        ),
        jar,
    )

def seed_from_files(
    path: Path,
    cookies_path: Path | None = None,
    *,
    require_private_cookies: bool = True,
) -> SessionSeed:
    inspection, jar = inspect_har(path)
    if cookies_path:
        _merge_cookies(jar, load_netscape_cookies(cookies_path, require_private=require_private_cookies))
        jar.clear_expired_cookies()
        inspection.cookie_count = sum(1 for _ in jar)
        inspection.has_sensitive_session = _session_cookies_ready(
            jar,
            inspection.api_base,
            inspection.web_base,
        )
    if not inspection.api_base:
        raise MissingSession("в HAR не найден текущий web-node API")
    if not inspection.web_base:
        raise MissingSession("в HAR не найден webN.online.sberbank.ru/main")
    if not inspection.cookie_count:
        raise MissingSession(
            "HAR экспортирован без cookies. В DevTools включите Preferences > Network > "
            "Allow to generate HAR with sensitive data и запишите вход заново"
        )
    if not inspection.has_sensitive_session:
        raise MissingSession(
            "cookies есть, но не подходят одновременно для web-node API и warmUpSession "
            "(проверьте domain/path/expiry в cookies.txt)"
        )
    return SessionSeed(
        api_base=inspection.api_base,
        web_base=inspection.web_base,
        cookies=jar,
        observed_headers=inspection.observed_headers,
    )

def _browser_headers(seed: SessionSeed) -> dict[str, str]:
    fallback = {
        "Accept": "application/json, text/plain, */*",
        "Content-Type": "application/json;charset=UTF-8",
        "Origin": "https://online.sberbank.ru",
        "Referer": "https://online.sberbank.ru/",
        "Sec-Fetch-Dest": "empty",
        "Sec-Fetch-Mode": "cors",
        "Sec-Fetch-Site": "same-site",
        "Priority": "u=1, i",
        "X-Requested-With": "XMLHttpRequest",
    }
    headers = {
        CANONICAL_HEADER_NAMES[name]: value
        for name, value in seed.observed_headers.items()
        if name in CANONICAL_HEADER_NAMES
    }
    for name, value in fallback.items():
        headers.setdefault(name, value)
    return headers

def _impersonation_profile(headers: Mapping[str, str]) -> str:
    client_hints = headers.get("sec-ch-ua", "")
    user_agent = headers.get("user-agent", "")
    if "Chromium" in client_hints or "Google Chrome" in client_hints or "Chrome/" in user_agent:
        return "chrome146"
    if "iPhone" in user_agent and "Safari/" in user_agent:
        return "safari184_ios"
    if "Safari/" in user_agent:
        return "safari184"
    return "chrome146"

def _request_moment(value: date | datetime, *, end: bool = False) -> datetime:
    if isinstance(value, datetime):
        moment = value
        if moment.tzinfo is not None:
            moment = moment.astimezone(MOSCOW).replace(tzinfo=None)
    else:
        moment = datetime.combine(value, time.max.replace(microsecond=0) if end else time.min)
    return moment

def _iso_moscow(value: date | datetime, *, end: bool = False) -> str:
    """ISO-8601 with the Moscow offset, e.g. 2026-08-01T00:00:00+03:00 (PFM API format)."""
    return _request_moment(value, end=end).strftime("%Y-%m-%dT%H:%M:%S") + "+03:00"

def __post_init__(self) -> None:
        if not isinstance(self.html, str) or not self.html or len(self.html) > 4 * 1024 * 1024 or not isinstance(self.url, str):
            raise PinAuthError("Browser document не поддерживается", code="unsupported_browser_state")
        if not isinstance(self.browser, BrowserProfile) or not isinstance(self.cookies, tuple) or len(self.cookies) > MAX_COOKIES or not all(isinstance(cookie, CookieRecord) for cookie in self.cookies):
            raise PinAuthError("Browser snapshot не поддерживается", code="unsupported_browser_state")
        keys = [(cookie.name, cookie.domain, cookie.path) for cookie in self.cookies]
        if len(keys) != len(set(keys)):
            raise PinAuthError("Browser snapshot содержит неоднозначные cookies", code="unsupported_browser_state")

def is_browser_check(html: str) -> bool:
    """Recognize the observed TSPD JS shell, not every malformed auth page."""
    if not isinstance(html, str) or len(html) > 4 * 1024 * 1024:
        return False
    lowered = html.lower()
    return (
        "/tspd/" in lowered and "<script" in lowered and "enable javascript" in lowered
        and re.search(r"\bwindow\s*\.\s*config\s*=", html) is None
    )

def __init__(self, profile_dir: Path, *, headless: bool = True, timeout: float = 30):
        if type(headless) is not bool:
            raise ValueError("headless должен быть bool")
        if type(timeout) not in (int, float) or not 0 < timeout <= 120:
            raise ValueError("timeout должен быть > 0 и <= 120 секунд")
        self.profile_dir = Path(profile_dir)
        self.headless = headless
        self.timeout = timeout

async def __call__(self, bundle: SessionBundle, url: str) -> BrowserBootstrapResult:
        failure_code = None
        result = None
        try:
            if url != f"{APP_ORIGIN}/CSAFront/index.do":
                raise PinAuthError("Небезопасный bootstrap URL", code="unsafe_bootstrap_request")
            info = self.profile_dir.lstat()
            if not stat.S_ISDIR(info.st_mode) or not hasattr(os, "getuid") or info.st_uid != os.getuid() or stat.S_IMODE(info.st_mode) & 0o077:
                raise PinAuthError("Нужен частный профиль владельца с mode 0700", code="unsupported_browser_state")
            result = await asyncio.wait_for(self._render(bundle, url), timeout=self.timeout)
        except TimeoutError as error:
            error.__traceback__ = None
            failure_code = "browser_bootstrap_timeout"
        except ImportError as error:
            error.__traceback__ = None
            failure_code = "browser_bootstrap_unavailable"
        except Exception as error:
            failure_code = error.code if isinstance(error, PinAuthError) and error.code in {
                "browser_owner_required", "unsupported_browser_state", "unsafe_bootstrap_request",
            } else "browser_bootstrap_failed"
            error.__traceback__ = None
        if failure_code is not None:
            raise PinAuthError("Browser bootstrap не завершён; проверьте optional browser extra, профиль и его CA; CAPTCHA требует владельца", code=failure_code)
        assert result is not None
        return result

async def _render(self, bundle: SessionBundle, url: str) -> BrowserBootstrapResult:
        # Lazy import: installing/importing the core SDK never needs Playwright.
        playwright = import_module("playwright.async_api")
        async with playwright.async_playwright() as runtime:
            env = {
                name: value for name, value in os.environ.items()
                if not name.lower().endswith("_proxy") and not name.startswith("MOZ_DISABLE_")
                and name not in {"DEBUG", "PWDEBUG", "SSLKEYLOGFILE", "MOZ_LOG", "MOZ_LOG_FILE", "PLAYWRIGHT_FIREFOX_POLICIES_JSON"}
            }
            context = await runtime.firefox.launch_persistent_context(
                str(self.profile_dir), headless=self.headless,
                java_script_enabled=True, ignore_https_errors=False,
                service_workers="block", accept_downloads=False,
                env=env,
                # Reject HTTP redirects rather than auto-following a target before
                # Playwright can inspect it. JS same-page navigation remains normal.
                firefox_user_prefs={"network.proxy.type": 0, "network.http.redirection-limit": 0},
            )
            html = ""
            raw_cookies = []
            try:
                await context.clear_cookies()
                await context.add_cookies([
                    _playwright_cookie(cookie) for cookie in bundle.cookies
                    if cookie.expires is None or cookie.expires > time.time()
                ])
                observed: dict[str, str] = {}
                status = None
                root_frame = None

                async def route_request(route: Any) -> None:
                    request = route.request
                    main_document = request.resource_type == "document" and request.frame.parent_frame is None
                    if main_document and request.frame is not root_frame:
                        await route.abort()
                        return
                    if not _public_bootstrap_request(request.url, request.method, request.resource_type, url, main_document=main_document):
                        await route.abort()
                        return
                    if request.resource_type == "document" and request.url == url and request.frame is root_frame:
                        headers = await request.all_headers()
                        observed.clear()
                        observed.update({
                            name: value for name, value in headers.items()
                            if name in {"user-agent", "accept-language", "sec-ch-ua", "sec-ch-ua-mobile", "sec-ch-ua-platform"}
                        })
                    await route.continue_()

                def response_received(response: Any) -> None:
                    nonlocal status
                    if response.url == url and response.request.resource_type == "document" and response.request.frame is root_frame:
                        status = response.status

                await context.route("**/*", route_request)
                await context.route_web_socket("**/*", lambda socket: socket.close())
                context.on("response", response_received)
                page = await context.new_page()
                root_frame = page.main_frame
                await page.goto(url, wait_until="domcontentloaded", timeout=self.timeout * 1000)
                while True:
                    try:
                        captcha = page.locator('iframe[src*="captcha" i], input[name*="captcha" i], img[src*="captcha" i]')
                        for index in range(await captcha.count()):
                            if await captcha.nth(index).is_visible():
                                raise PinAuthError("CAPTCHA требует владельца браузера", code="browser_owner_required")
                        html = await page.content()
                        if re.search(r"\bwindow\s*\.\s*config\s*=", html):
                            break
                        if await page.evaluate('() => typeof window.config === "object" && window.config !== null'):
                            raise PinAuthError("Config не представлен строгим HTML literal", code="unsupported_browser_state")
                    except playwright.Error as error:
                        # DOM access may race ordinary JS navigation. Wait within
                        # the same bound; never log raw browser error contents.
                        error.__traceback__ = None
                    await asyncio.sleep(0.1)
                final_url = page.url
                # Freeze document scripts/network before reading the complete jar.
                await page.close()
                raw_cookies = await context.cookies()
                if len(raw_cookies) > MAX_COOKIES:
                    raise PinAuthError("Слишком много browser cookies", code="unsupported_browser_state")
                cookies = tuple(_cookie_from_playwright(cookie) for cookie in raw_cookies)
                if status != 200 or final_url != url:
                    raise PinAuthError("Browser bootstrap не выдал auth страницу", code="browser_bootstrap_failed")
                return BrowserBootstrapResult(html, cookies, BrowserProfile.from_mapping(observed), final_url)
            finally:
                html = ""
                raw_cookies = []
                await context.close()

