                    if response.url == url and response.request.resource_type == "document" and response.request.frame is root_frame:
                        status = response.status

def _public_bootstrap_request(url: str, method: str, resource_type: str, target: str, *, main_document: bool = True) -> bool:
    if method != "GET" or not _online_url(url) or "\\" in url or any(ord(char) < 0x20 for char in url):
        return False
    path = unquote(urlsplit(url).path).lower()
    if "/api/" in path or "authmainjson.do" in path or "captcha" in path:
        return False
    if resource_type == "document":
        return url == target if main_document else path.startswith("/tspd/")
    return path.startswith("/tspd/") or bool(re.search(r"\.(?:js|css|png|jpg|jpeg|gif|svg|ico|woff2?|ttf)\Z", path))

def _playwright_cookie(cookie: CookieRecord) -> dict[str, Any]:
    result: dict[str, Any] = {
        "name": cookie.name, "value": cookie.value,
        "domain": cookie.domain if cookie.host_only else "." + cookie.domain,
        "path": cookie.path, "secure": cookie.secure, "httpOnly": cookie.http_only,
    }
    if cookie.expires is not None:
        result["expires"] = cookie.expires
    if cookie.same_site is not None:
        result["sameSite"] = cookie.same_site
    return result

def _cookie_from_playwright(cookie: dict[str, Any]) -> CookieRecord:
    invalid = False
    record = None
    try:
        required = {"name", "value", "domain", "path", "secure", "httpOnly", "expires", "sameSite"}
        if not required <= cookie.keys() or not cookie.keys() <= required | {"partitionKey"} or cookie.get("partitionKey") is not None:
            raise ValueError("unsupported metadata")
        expiry = cookie["expires"]
        if type(expiry) not in (int, float) or not math.isfinite(expiry) or (expiry != -1 and expiry <= 0):
            raise ValueError("unsupported expiry")
        record = CookieRecord(
            cookie["name"], cookie["value"], cookie["domain"], path=cookie["path"],
            secure=cookie["secure"], http_only=cookie["httpOnly"],
            host_only=not cookie["domain"].startswith("."),
            expires=None if expiry == -1 else int(expiry), same_site=cookie["sameSite"],
        )
    except (TypeError, ValueError, KeyError, AttributeError) as error:
        error.__traceback__ = None
        invalid = True
    if invalid:
        raise PinAuthError("Browser cookie metadata не поддерживается", code="unsupported_browser_state")
    assert record is not None
    return record

def from_session_file(cls, path: Path, *, require_private: bool = True, ca_bundle: str | Path | None = None) -> "AsyncSberClient":
        bundle = SessionBundle.load(path, require_private=require_private)
        client = cls(bundle, ca_bundle=ca_bundle)
        client._session_path = Path(path)
        client._save_credentials_only = (
            len(bundle.cookies) == 2
            and {cookie.name for cookie in bundle.cookies} == {"UFS-SESSION", "UFS-TOKEN"}
        )
        return client

async def _close_owned_transports(self) -> None:
        if self._close_complete:
            return
        self._closed = True
        self._pin_provider = None
        failures: list[Exception] = []
        for transport in (self._transport, *self._retired_transports):
            try:
                await transport.aclose()
            except Exception as error:
                failures.append(error)
        if failures:
            raise failures[0]
        self._retired_transports.clear()
        self._close_complete = True

async def warm_up(self, *, force: bool = True) -> None:
        if self._pin_provider is None:
            await self._ensure_warm_up(force=force)
            return
        arrival_epoch = self._reauth_epoch
        async with self._profile_request_lock:
            try:
                await self._ensure_warm_up(force=force)
            except AuthenticationExpired:
                if arrival_epoch != self._reauth_epoch:
                    raise
                try:
                    await self._reauthenticate_profile()
                    await self._ensure_warm_up(force=force)
                finally:
                    self._reauth_epoch += 1

def _warmup_due(self) -> bool:
        return self._last_warmup is None or (
            self._monotonic() - self._last_warmup >= WARMUP_DEBOUNCE_SECONDS
        )

async def _post(self, path: str, payload: Mapping[str, Any]) -> Mapping[str, Any]:
        if path not in READ_PATHS:
            raise ValueError(f"endpoint не входит в read-only allowlist: {path}")
        if self._pin_provider is None:
            return await self._post_once(path, payload)
        arrival_epoch = self._reauth_epoch
        # Keep profile requests behind one lock: after the first 401 only one
        # coroutine renews the PIN session and all waiters reuse it.
        async with self._profile_request_lock:
            try:
                response = await self._post_once(path, payload)
            except AuthenticationExpired:
                if arrival_epoch != self._reauth_epoch:
                    raise
                try:
                    await self._reauthenticate_profile()
                    response = await self._post_once(path, payload)
                finally:
                    self._reauth_epoch += 1
            return response

async def _mutate(
        self,
        path: str,
        payload: Mapping[str, Any],
        *,
        query: Mapping[str, str],
        page_id: str,
        workflow: bool = False,
    ) -> Mapping[str, Any]:
        """Send one mutation attempt; unlike _post(), never reauthenticate and replay it."""
        if path not in MUTATION_PATHS:
            raise ValueError(f"endpoint не входит в mutation allowlist: {path}")
        if not isinstance(page_id, str) or not page_id.startswith("/") or any(
            ord(char) < 0x20 or ord(char) == 0x7F for char in page_id
        ):
            raise ValueError("page_id должен быть безопасным относительным путём")
        async with self._mutation_lock:
            if self._pin_provider is None:
                return await self._mutate_once(path, payload, query, page_id, workflow)
            async with self._profile_request_lock:
                return await self._mutate_once(path, payload, query, page_id, workflow)

async def _mutate_once(
        self,
        path: str,
        payload: Mapping[str, Any],
        query: Mapping[str, str],
        page_id: str,
        workflow: bool,
    ) -> Mapping[str, Any]:
        deviceprint = self.bundle.antifraud_deviceprint
        if deviceprint is None:
            raise MissingSession(
                "для мутаций нужен SessionBundle с antifraud_deviceprint из "
                "window.bfd.getEncodedData()"
            )
        headers = {
            "RSA-Antifraud-Device-Print": deviceprint,
            "RSA-Antifraud-Page-Id": page_id,
        }
        if workflow:
            headers["X-Workflow-Options"] = "3.0"
        base = await self._resolve_api_base()
        try:
            response = await self._request(
                base,
                path,
                payload,
                query=query,
                headers=headers,
            )
        except asyncio.CancelledError as error:
            raise MutationUncertain(
                "mutation была отменена после начала отправки; результат неизвестен"
            ) from error
        try:
            self._save_rotated_session()
        except Exception as error:
            raise MutationUncertain(
                "mutation была принята сервером, но обновлённую сессию не удалось сохранить"
            ) from error
        return response

async def _get_html(self, url: str) -> str:
        if self._closed:
            raise TransportError("client уже закрыт")
        response = await self._transport.get(
            url,
            accept_encoding="gzip, deflate, br, zstd",
        )
        if response.status_code in (301, 302, 303, 307, 308, 401, 403):
            raise AuthenticationExpired("сессия СберБанк Онлайн истекла или отклонена")
        if response.status_code != 200:
            raise ApiError(f"Сбер вернул HTTP {response.status_code} при discovery")
        if not isinstance(response.text, str):
            raise ApiError("Сбер вернул некорректный HTML при discovery")
        return response.text

async def _request(
        self,
        base: str,
        path: str,
        payload: Mapping[str, Any],
        *,
        query: Mapping[str, str] | None = None,
        headers: Mapping[str, str | None] | None = None,
    ) -> Mapping[str, Any]:
        if self._closed:
            raise TransportError("client уже закрыт")
        if path not in READ_PATHS | MUTATION_PATHS | {WARMUP_PATH}:
            raise ValueError(f"endpoint не входит в allowlist: {path}")
        url = f"{base.rstrip('/')}{path}"
        if query:
            url = f"{url}?{urlencode(query)}"
        kwargs: dict[str, Any] = {
            "json": payload,
            "accept_encoding": "gzip, deflate, br, zstd",
        }
        if headers is not None:
            kwargs["headers"] = headers
        response = await self._transport.post(url, **kwargs)
        return _decode_response(response, path)

def export_session(self) -> SessionBundle:
        """Snapshot cookies after every Set-Cookie already applied by the transport."""
        return self.bundle.with_cookie_jar(self._transport.cookie_jar())

def export_credentials(self) -> SberCredentials:
        """Return rotated auth values in memory without serializing a cookie jar."""
        return SberCredentials.from_bundle(self.export_session())

def _decode_response(response: ResponseLike, path: str) -> Mapping[str, Any]:
    if response.status_code in (301, 302, 303, 307, 308, 401, 403):
        raise AuthenticationExpired("сессия СберБанк Онлайн истекла или отклонена")
    content_type = next(
        (
            str(value).lower()
            for name, value in response.headers.items()
            if str(name).lower() == "content-type"
        ),
        "",
    )
    if path == WARMUP_PATH and response.status_code in (200, 204):
        if "text/html" in content_type:
            raise AuthenticationExpired("вместо API-ответа получена страница входа")
        return {}
    if response.status_code != 200:
        raise ApiError(f"Сбер вернул HTTP {response.status_code}")
    if "text/html" in content_type:
        raise AuthenticationExpired("вместо API-ответа получена страница входа")
    try:
        data = response.json()
    except Exception as exc:
        raise ApiError("Сбер вернул некорректный JSON") from exc
    if not isinstance(data, Mapping):
        raise ApiError("ожидался JSON object")
    success = data.get("success")
    if not (success is True or success == "true"):
        error = data.get("error")
        details = error if isinstance(error, Mapping) else {}
        code = _bounded_error_field(details, "code", 128)
        raise ApiRejected(
            f"API success=false{f', code={code}' if code else ''}",
            code=code,
            title=_bounded_error_field(details, "title", 4096),
            text=_bounded_error_field(details, "text", 4096),
            uuid=_bounded_error_field(details, "uuid", 256),
            system=_bounded_error_field(details, "system", 256),
        )
    return data

def _bounded_error_field(error: Mapping[str, Any], name: str, limit: int) -> str | None:
    value = error.get(name)
    if (
        not isinstance(value, str)
        or not value
        or len(value) > limit
        or any((ord(char) < 0x20 and char not in "\t\n") or ord(char) == 0x7F for char in value)
    ):
        return None
    return value

async def _pin_login(
    bundle: SessionBundle,
    provider: str | Callable[[], str],
    *,
    browser_bootstrap: BrowserBootstrapProvider | None = None,
    browser_bootstrap_timeout: float = 30,
    ca_bundle: str | Path | None = None,
) -> SessionBundle:
    pin = provider() if callable(provider) else provider
    if not isinstance(pin, str) or not pin:
        raise ValueError("PIN provider должен вернуть непустую строку")
    options: dict[str, Any] = {}
    if browser_bootstrap is not None:
        options["browser_bootstrap"] = browser_bootstrap
    if browser_bootstrap_timeout != 30:
        options["browser_bootstrap_timeout"] = browser_bootstrap_timeout
    if ca_bundle is not None:
        options["ca_bundle"] = ca_bundle
    try:
        async with AsyncPinAuth(bundle, **options) as auth:
            return await auth.login(pin)
    finally:
        pin = ""

def operation_resource(self) -> str:
        if self.kind == "ctaccount":
            return f"ct-account:{self.id}"
        if self.kind == "account":
            return f"account:{self.id}"
        raise ValueError(f"неизвестный kind счёта: {self.kind!r}")

def transfer_resource(self) -> str:
        if self.kind == "ctaccount":
            return f"transactionAccount:{self.id}"
        if self.kind == "account":
            return f"account:{self.id}"
        raise ValueError(f"неизвестный kind счёта: {self.kind!r}")

def account(self) -> BankAccount | None:
        """Account resolved from this product snapshot, not proof of bank-side absence."""
        return (
            self._portfolio._accounts_by_id.get(self.account_id)
            if self.account_id
            else None
        )

def __init__(self, raw: Products, client: _Client):
        if not isinstance(raw, Products):
            raise TypeError("raw должен быть Products")
        self._raw = raw
        self._accounts = tuple(BankAccount(item, client, self) for item in raw.accounts)
        self._cards = tuple(BankCard(item, client, self) for item in raw.cards)

        # Only ctaccount ids ever appear as card.account_id (see parse_products),
        # so bucket by ctaccount id alone; an account with a colliding id must not
        # count as a duplicate and erase the real relation.
        account_buckets: dict[str, list[BankAccount]] = {}
        for account in self._accounts:
            if account.id and account.kind == "ctaccount":
                account_buckets.setdefault(account.id, []).append(account)
        self._accounts_by_id = {
            account_id: items[0]
            for account_id, items in account_buckets.items()
            if len(items) == 1
        }

        cards_by_account: dict[int, list[BankCard]] = {
            id(account): [] for account in self._accounts
        }
        for card in self._cards:
            resolved = card.account
            if resolved is not None:
                cards_by_account[id(resolved)].append(card)
        self._cards_by_account = {
            account_id: tuple(items)
            for account_id, items in cards_by_account.items()
        }

def _json_content(entry: Mapping[str, Any]) -> Mapping[str, Any] | None:
    response = _optional_mapping(entry.get("response"))
    content = _optional_mapping(response.get("content"))
    text = content.get("text")
    if not isinstance(text, str):
        return None
    if content.get("encoding") == "base64":
        try:
            text = base64.b64decode(text).decode("utf-8")
        except (binascii.Error, UnicodeDecodeError):
            return None
    try:
        value = json.loads(text)
    except (UnicodeDecodeError, ValueError):
        return None
    return value if isinstance(value, Mapping) else None

def _request_scopes(entry: Mapping[str, Any]) -> list[str]:
    request = _optional_mapping(entry.get("request"))
    post_data = _optional_mapping(request.get("postData"))
    text = post_data.get("text")
    if not isinstance(text, str):
        return []
    try:
        value = json.loads(text)
    except ValueError:
        return []
    scopes = value.get("usedResource", []) if isinstance(value, Mapping) else []
    if isinstance(scopes, str):
        return [scopes]
    return [_id(scope) for scope in scopes if scope is not None] if isinstance(scopes, list) else []

def _is_sber_url(url: Any) -> bool:
    try:
        parsed = urlsplit(_id(url))
    except ValueError:
        return False
    host = (parsed.hostname or "").lower()
    return parsed.scheme == "https" and (host == "online.sberbank.ru" or host.endswith(".online.sberbank.ru"))

def _signed_money(value: Money | None, direction: str) -> Money | None:
    if value is None:
        return None
    amount = abs(value.amount)
    return Money(-amount if direction == "out" else amount, value.currency)

def _ledger(operations: Iterable[Operation]) -> list[CardLedgerEntry]:
    entries: dict[tuple[str, str, str], CardLedgerEntry] = {}
    for operation in operations:
        direct_cards: set[str] = set()
        for resource, direction in ((operation.from_resource, "out"), (operation.to_resource, "in")):
            if not resource or resource.type != "card":
                continue
            direct_cards.add(resource.id)
            entry = CardLedgerEntry(operation.id, resource.id, direction, _signed_money(operation.amount, direction))
            entries[(operation.id, resource.id, direction)] = entry

        for card_id in sorted(set(operation.scope_card_ids) - direct_cards):
            if operation.amount is None:
                direction = "unknown"
            elif operation.amount.amount < 0:
                direction = "out"
            elif operation.amount.amount > 0:
                direction = "in"
            else:
                direction = "neutral"
            entry = CardLedgerEntry(operation.id, card_id, direction, operation.amount)
            entries[(operation.id, card_id, direction)] = entry
    return list(entries.values())

def parse_har(har: Mapping[str, Any]) -> dict[str, Any]:
    """Parse all cached responses in a HAR; request headers/cookies are deliberately ignored."""
    log = _mapping(har.get("log"), "HAR log")
    entries = log.get("entries", [])
    if not isinstance(entries, list):
        raise ParseError("HAR log.entries: ожидался массив")

    accounts_by_id: dict[str, Account] = {}
    cards_by_id: dict[str, Card] = {}
    operations_by_id: dict[str, Operation] = {}
    ledger_by_key: dict[tuple[str, str, str], CardLedgerEntry] = {}
    matched = {"products": 0, "operations": 0, "missing_content": 0}

    for entry in entries:
        if not isinstance(entry, Mapping):
            continue
        request = _optional_mapping(entry.get("request"))
        if str(request.get("method", "")).upper() != "POST":
            continue
        if not _is_sber_url(request.get("url")):
            continue
        path = urlsplit(_id(request.get("url"))).path
        if path not in (PRODUCTS_PATH, OPERATIONS_PATH):
            continue
        payload = _json_content(entry)
        if payload is None:
            matched["missing_content"] += 1
            continue
        success = payload.get("success")
        if not (success is True or success == "true"):
            continue
        if path == PRODUCTS_PATH:
            matched["products"] += 1
            accounts, cards = parse_products(payload)
            accounts_by_id.update((account.id, account) for account in accounts if account.id)
            cards_by_id.update((card.id, card) for card in cards if card.id)
        else:
            matched["operations"] += 1
            for operation in parse_operations(payload, _request_scopes(entry)):
                if operation.id:
                    for ledger_entry in _ledger([operation]):
                        key = (ledger_entry.operation_id, ledger_entry.card_id, ledger_entry.direction)
                        ledger_by_key[key] = ledger_entry
                    previous = operations_by_id.get(operation.id)
                    if previous:
                        operation = replace(
                            operation,
                            scope_card_ids=tuple(
                                sorted(set(previous.scope_card_ids) | set(operation.scope_card_ids))
                            ),
                        )
                    operations_by_id[operation.id] = operation

    operations = sorted(
        operations_by_id.values(),
        key=lambda item: operation_sort_key(item.date),
        reverse=True,
    )
    return {
        "cards": list(cards_by_id.values()),
        "accounts": list(accounts_by_id.values()),
        "operations": operations,
        "card_ledger": list(ledger_by_key.values()),
        "capture": matched,
    }

