def _mapping(value: Any, name: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ParseError(f"{name}: ожидался JSON object")
    return value

def _luhn(number: str) -> bool:
    total = 0
    parity = len(number) % 2
    for index, char in enumerate(number):
        digit = int(char)
        if index % 2 == parity:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0

def _text(value: Any) -> str:
    text = _id(value)

    def redact(match: re.Match[str]) -> str:
        digits = re.sub(r"\D", "", match.group())
        return f"•••• {digits[-4:]}" if _luhn(digits) else match.group()

    return PAN_CANDIDATE.sub(redact, text)

def redact(match: re.Match[str]) -> str:
        digits = re.sub(r"\D", "", match.group())
        return f"•••• {digits[-4:]}" if _luhn(digits) else match.group()

def _decimal(value: Any) -> Decimal:
    if isinstance(value, bool) or value is None:
        raise ParseError("денежная сумма отсутствует или имеет неверный тип")
    try:
        result = Decimal(str(value).replace(",", "."))
    except InvalidOperation as error:
        raise ParseError(f"неверная денежная сумма: {value!r}") from error
    if not result.is_finite():
        raise ParseError(f"нефинитная денежная сумма: {value!r}")
    return result

def _money(value: Any) -> Money | None:
    if not isinstance(value, Mapping) or value.get("amount") is None:
        return None
    # or-chain so an explicit currencyCode:null falls back instead of becoming "".
    currency: Any = value.get("currencyCode") or value.get("currency") or ""
    if isinstance(currency, Mapping):
        currency = currency.get("code", "")
    return Money(_decimal(value["amount"]), currency if isinstance(currency, str) else "")

def _soft_money(value: Any) -> Money | None:
    """Optional amount fields tolerate a malformed value instead of aborting the page."""
    try:
        return _money(value)
    except ParseError:
        return None

def _data_list(section: Any, name: str) -> list:
    """A product section's ``data`` must be a list; a scalar there is a hard error."""
    data = _optional_mapping(section).get("data")
    if data is None:
        return []
    if not isinstance(data, list):
        raise ParseError(f"{name}.data: ожидался массив")
    return data

def operation_sort_key(date: str) -> datetime:
    """Timezone-aware comparable key for ``Operation.date`` (ISO on success, raw on
    parse failure); unparseable dates sort oldest so one bad value can't reorder the rest."""
    try:
        moment = datetime.fromisoformat(date)
    except ValueError:
        return datetime.min.replace(tzinfo=timezone.utc)
    return moment if moment.tzinfo is not None else moment.replace(tzinfo=MOSCOW)

def _last4(value: Any) -> str:
    digits = re.sub(r"\D", "", str(value or ""))
    return digits[-4:]

def _resource(value: Any) -> Resource | None:
    if not isinstance(value, Mapping) or not value.get("id"):
        return None
    raw = _id(value["id"])
    resource_type, separator, resource_id = raw.partition(":")
    return Resource(resource_type if separator else "unknown", resource_id if separator else raw)

def _operation_date(value: Any) -> str:
    raw = str(value or "")
    try:
        return datetime.strptime(raw, "%d.%m.%YT%H:%M:%S").replace(tzinfo=MOSCOW).isoformat()
    except ValueError:
        return raw

def _jsonable(value: Any) -> Any:
    if isinstance(value, Decimal):
        return str(value)
    if hasattr(value, "__dataclass_fields__"):
        return {key: _jsonable(item) for key, item in asdict(value).items()}
    if isinstance(value, Mapping):
        return {str(key): _jsonable(item) for key, item in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable(item) for item in value]
    return value

