            f"TransferResult(pid=<redacted>, flow={self.flow!r}, state={self.state!r}, "
            f"document_id={'<present>' if self.document_id is not None else None})"
        )

def _int(value: Any) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return 0

def _credit_info(value: Any) -> CreditInfo | None:
    credit = _optional_mapping(value)
    if not credit:
        return None
    return CreditInfo(
        limit=_soft_money(credit.get("creditLimit")),
        own_sum=_soft_money(credit.get("creditOwnSum")),
        debt=_soft_money(credit.get("creditDebt")),
        min_payment=_soft_money(credit.get("creditMinPayment")),
        min_payment_date=_text(credit.get("creditMinPaymentDate")),
    )

def __init__(self, n_hex: str, g_hex: str, *, private_a_hex: str | None = None):
        self.n = _hex_int("N", n_hex)
        self.g = _hex_int("g", g_hex)
        if self.n <= 3 or not 1 < self.g < self.n:
            raise ValueError("некорректная SRP-группа")
        self.pad_length = (self.n.bit_length() + 7) // 8
        if private_a_hex is None:
            byte_length = self.pad_length // 8
            if byte_length == 0:
                raise ValueError("SRP-группа слишком мала")
            self.a = 0
            while self.a == 0:
                self.a = int.from_bytes(secrets.token_bytes(byte_length), "big")
        else:
            self.a = _hex_int("a", private_a_hex)
            if self.a == 0:
                raise ValueError("SRP private a не может быть нулём")
        self.A = pow(self.g, self.a, self.n)
        if self.A == 0:
            raise ValueError("некорректное SRP public A")
        self._expected_m2: bytes | None = None

def verify_server_proof(self, proof_hex: str) -> bool:
        if self._expected_m2 is None:
            raise RuntimeError("SRP challenge ещё не обработан")
        try:
            proof = _hex_int("server proof", proof_hex)
            if proof.bit_length() > 512:
                return False
            supplied = proof.to_bytes(64, "big")
        except (ValueError, OverflowError):
            return False
        return compare_digest(self._expected_m2, supplied)

def _pad(self, value: int) -> bytes:
        raw = _int_bytes(value)
        return raw if len(raw) >= self.pad_length else raw.rjust(self.pad_length, b"\0")

def export_session(self) -> SessionBundle:
        """Snapshot remembered-browser/auth cookies after any Set-Cookie rotation."""
        self._ensure_open()
        return self.bundle.with_cookie_jar(self._transport.cookie_jar())

async def _render_bootstrap(self, bundle: SessionBundle) -> BrowserBootstrapResult:
        assert self._browser_bootstrap is not None
        failure_code = None
        result = None
        try:
            result = await asyncio.wait_for(
                self._browser_bootstrap(bundle, AUTH_PAGE),
                timeout=self._browser_bootstrap_timeout,
            )
            if not isinstance(result, BrowserBootstrapResult):
                failure_code = "unsupported_browser_state"
        except TimeoutError as error:
            error.__traceback__ = None
            failure_code = "browser_bootstrap_timeout"
        except Exception as error:
            # Browser errors can contain URLs/HTML/cookies; do not chain them.
            failure_code = error.code if isinstance(error, PinAuthError) and error.code in {
                "browser_owner_required", "unsupported_browser_state", "browser_bootstrap_unavailable",
                "unsafe_bootstrap_request", "browser_bootstrap_timeout",
            } else "browser_bootstrap_failed"
            error.__traceback__ = None
        if failure_code is not None:
            raise PinAuthError("Browser bootstrap не завершён; проверьте браузер/CA или обратитесь к владельцу", code=failure_code)
        assert isinstance(result, BrowserBootstrapResult)
        return result

def _update_csrf(self, response: ResponseLike) -> None:
        value = _header(response.headers, "x-csrf-token")
        if value:
            if len(value) > 8192 or "\r" in value or "\n" in value:
                raise PinAuthError("Сервер вернул некорректный CSRF token", code="invalid_csrf")
            self._csrf_token = value

def _with_context(self, body: Mapping[str, Any]) -> dict[str, Any]:
        result = dict(body)
        if self._deviceprint is not None:
            result["deviceprint"] = self._deviceprint
        if self._is_pwa:
            result["isPwa"] = True
        return result

def _require_otp(self) -> _PinRuntime:
        if not self._otp_pending or self._config is None:
            raise PinAuthError("Активного SMS challenge нет", code="otp_not_pending")
        return self._config

def _ensure_open(self) -> None:
        if self._closed:
            raise RuntimeError("PIN auth client уже закрыт")

async def retry_otp(self) -> PinOtpRequired:
        async with self._lock:
            self._ensure_open()
            config, token, _ = self._require_primary_otp()
            response = await self._post_primary_form(
                config,
                {
                    **self._primary_context(),
                    "org.apache.struts.taglib.html.TOKEN": token,
                    "operation": "button.getNewPass",
                    "pageInputType": "INDEX",
                    "token": token,
                },
            )
            self._primary_token = _optional_auth_token(response) or token
            if response.get("state") == "ATTEMPTS_EXHAUSTED" or _form_true(
                response.get("smsRequestAttemptsExhausted")
            ):
                raise PinAuthError(
                    "Лимит запросов нового SMS-кода исчерпан",
                    code="attempts_limit_reached",
                )
            return PinOtpRequired(
                lifetime=_coerce_nonnegative_int(response.get("timeout")),
                remaining_attempts=None,
            )

async def _consume_primary_response(
        self,
        config: _PinRuntime,
        payload: Mapping[str, Any],
    ) -> SessionBundle | None:
        token = _optional_auth_token(payload)
        if token is not None:
            self._primary_token = token
        state = payload.get("state")
        if state == "NEED_CONFIRM":
            if self._primary_token is None:
                raise PinAuthError("SMS challenge не содержит token", code="invalid_otp_challenge")
            self._primary_otp_pending = True
            raise PinOtpRequired(
                lifetime=_coerce_nonnegative_int(payload.get("timeout")),
                remaining_attempts=None,
            )
        if state == "WRONG_PASS":
            raise PinAuthError("SMS-код неверен", code="wrong_code")
        # smsRequestAttemptsExhausted means "no more resends" and rides along on
        # NOT_REQUIRED/WRONG_PASS success payloads; only the explicit state is terminal.
        if state == "ATTEMPTS_EXHAUSTED":
            self._primary_otp_pending = False
            raise PinAuthError("Лимит SMS-попыток исчерпан", code="attempts_limit_reached")

        pin_info = payload.get("pinInfo")
        if isinstance(pin_info, Mapping):
            if _form_true(pin_info.get("webPinSkip")):
                return await self._finish_primary_auth(config)
            public_key = pin_info.get("publicKey")
            if isinstance(public_key, str) and public_key:
                self._pin_public_key = public_key
                return None
        redirect = payload.get("redirect")
        if isinstance(redirect, str) and redirect:
            return await self._finish_redirect(config, redirect)
        if payload.get("webAuthnInfo") is not None:
            raise PinAuthError(
                "Сервер требует неподдерживаемый обязательный WebAuthn шаг",
                code="webauthn_required",
            )
        raise PinAuthError(
            "Primary auth не вернул pinInfo или redirect",
            code="invalid_primary_auth_state",
        )

async def _finish_primary_auth(self, config: _PinRuntime) -> SessionBundle:
        response = await self._post(config, AUTH_FINISH, self._with_context({}))
        redirect = response.get("redirect")
        if not isinstance(redirect, str) or not redirect:
            raise PinAuthError(
                "В финальном auth-ответе нет redirect",
                code="missing_redirect",
            )
        return await self._finish_redirect(config, redirect)

def _primary_context(self) -> dict[str, str]:
        return {
            "deviceprint": self._deviceprint,
            "jsEvents": "",
            "domElements": "",
        }

def _require_primary_otp(self) -> tuple[_PinRuntime, str, PinSrp]:
        if (
            not self._primary_otp_pending
            or self._config is None
            or self._primary_token is None
            or self._primary_srp is None
        ):
            raise PinAuthError("Активного primary SMS challenge нет", code="otp_not_pending")
        return self._config, self._primary_token, self._primary_srp

def _frontend_config_properties(html: str) -> dict[str, str]:
    if not isinstance(html, str) or not html or len(html) > 4 * 1024 * 1024:
        raise ValueError("invalid auth HTML")
    assignments = list(_CONFIG_ASSIGNMENT.finditer(html))
    if len(assignments) != 1:
        raise ValueError("window.config assignment must be unique")
    start = _skip_space_comments(html, assignments[0].end())
    if start >= len(html) or html[start] != "{":
        raise ValueError("window.config must be an object literal")
    config_source, _ = _balanced_object(html, start)
    return _object_properties(config_source)

def _validated_process_id(config: Mapping[str, str]) -> str:
    process_id = _literal_string(config, "processId")
    if not process_id or len(process_id) > 512 or _has_controls(process_id):
        raise ValueError("invalid processId")
    return process_id

def _balanced_object(source: str, start: int) -> tuple[str, int]:
    depth = 0
    index = start
    while index < len(source):
        char = source[index]
        if char in "\"'`":
            index = _skip_string(source, index)
            continue
        if char == "/" and index + 1 < len(source) and source[index + 1] in "/*":
            index = _skip_comment(source, index)
            continue
        if char == "{":
            depth += 1
        elif char == "}":
            depth -= 1
            if depth == 0:
                return source[start:index + 1], index + 1
            if depth < 0:
                break
        index += 1
    raise ValueError("unterminated object literal")

def _object_properties(source: str) -> dict[str, str]:
    if not isinstance(source, str):
        raise TypeError("object source")
    index = _skip_space_comments(source, 0)
    if index >= len(source) or source[index] != "{":
        raise ValueError("expected object literal")
    index += 1
    result: dict[str, str] = {}
    while True:
        index = _skip_space_comments(source, index)
        if index >= len(source):
            raise ValueError("unterminated object")
        if source[index] == "}":
            if _skip_space_comments(source, index + 1) != len(source):
                raise ValueError("trailing object data")
            return result
        key, index = _property_key(source, index)
        index = _skip_space_comments(source, index)
        if index >= len(source) or source[index] != ":":
            raise ValueError("object key without colon")
        index = _skip_space_comments(source, index + 1)
        value_start = index
        index = _property_value_end(source, index)
        value = source[value_start:index].strip()
        if not value or key in result:
            raise ValueError("empty or duplicate object property")
        result[key] = value
        index = _skip_space_comments(source, index)
        if index >= len(source):
            raise ValueError("unterminated object")
        if source[index] == ",":
            index += 1
            continue
        if source[index] != "}":
            raise ValueError("invalid object delimiter")

def _property_key(source: str, index: int) -> tuple[str, int]:
    if source[index] == '"':
        end = _skip_string(source, index)
        try:
            key = json.loads(source[index:end])
        except json.JSONDecodeError as error:
            raise ValueError("invalid quoted key") from error
        if not isinstance(key, str):
            raise ValueError("object key must be a string")
        return key, end
    match = _IDENTIFIER.match(source, index)
    if match is None:
        raise ValueError("invalid object key")
    return match.group(0), match.end()

def _property_value_end(source: str, index: int) -> int:
    stack: list[str] = []
    pairs = {"{": "}", "[": "]", "(": ")"}
    while index < len(source):
        char = source[index]
        if char in "\"'`":
            index = _skip_string(source, index)
            continue
        if char == "/" and index + 1 < len(source) and source[index + 1] in "/*":
            index = _skip_comment(source, index)
            continue
        if char in pairs:
            stack.append(pairs[char])
        elif char in "}])":
            if stack:
                if char != stack.pop():
                    raise ValueError("mismatched value delimiter")
            elif char == "}":
                return index
            else:
                raise ValueError("unexpected value delimiter")
        elif char == "," and not stack:
            return index
        index += 1
    raise ValueError("unterminated property value")

def _skip_space_comments(source: str, index: int) -> int:
    while index < len(source):
        if source[index].isspace():
            index += 1
        elif source[index] == "/" and index + 1 < len(source) and source[index + 1] in "/*":
            index = _skip_comment(source, index)
        else:
            break
    return index

def _skip_string(source: str, index: int) -> int:
    quote = source[index]
    index += 1
    while index < len(source):
        if source[index] == "\\":
            index += 2
        elif source[index] == quote:
            return index + 1
        else:
            index += 1
    raise ValueError("unterminated string")

def _skip_comment(source: str, index: int) -> int:
    if source[index:index + 2] == "//":
        end = source.find("\n", index + 2)
        return len(source) if end < 0 else end + 1
    if source[index:index + 2] == "/*":
        end = source.find("*/", index + 2)
        if end < 0:
            raise ValueError("unterminated comment")
        return end + 2
    return index

def _literal_string(properties: Mapping[str, str], key: str) -> str:
    raw = properties.get(key)
    if raw is None or not raw.startswith('"'):
        raise ValueError(f"{key} must be a JSON string literal")
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as error:
        raise ValueError(f"invalid {key}") from error
    if not isinstance(value, str):
        raise ValueError(f"invalid {key}")
    return value

def _literal_bool(properties: Mapping[str, str], key: str) -> bool:
    raw = properties.get(key)
    if raw == "true":
        return True
    if raw == "false":
        return False
    raise ValueError(f"invalid {key}")

def _literal_int(properties: Mapping[str, str], key: str) -> int:
    raw = properties.get(key)
    if raw is None or re.fullmatch(r"-?(?:0|[1-9][0-9]*)", raw) is None:
        raise ValueError(f"invalid {key}")
    return int(raw)

def _normalize_auth_base(value: str) -> str:
    if not value or value != value.strip() or _has_controls(value) or "\\" in value:
        raise ValueError("invalid auth base")
    if _online_url(value):
        parsed = urlsplit(value)
        if parsed.query or parsed.fragment:
            raise ValueError("auth base cannot contain query or fragment")
        return value.rstrip("/")
    parsed = urlsplit(value)
    if parsed.scheme or parsed.netloc or parsed.query or parsed.fragment:
        raise ValueError("invalid relative auth base")
    pieces = [piece for piece in parsed.path.split("/") if piece]
    if not pieces or any(piece in {".", ".."} for piece in pieces):
        raise ValueError("invalid relative auth base")
    result = f"{APP_ORIGIN}/{'/'.join(pieces)}"
    if not _online_url(result):
        raise ValueError("invalid auth base host")
    return result

def _endpoint(base: str, path: str) -> str:
    result = f"{base.rstrip('/')}/{path.lstrip('/')}"
    if not _online_url(result):
        raise PinAuthError("Endpoint вышел за online.sberbank.ru", code="unsafe_endpoint")
    return result

def _safe_online_url(value: str, *, base: str) -> str:
    if not isinstance(value, str) or not value or _has_controls(value) or "\\" in value:
        raise PinAuthError("Сервер вернул небезопасный URL", code="unsafe_redirect")
    result = urljoin(base, value)
    if not _online_url(result):
        raise PinAuthError("Сервер вернул внешний URL", code="unsafe_redirect")
    parsed = urlsplit(result)
    return urlunsplit((parsed.scheme, parsed.netloc, parsed.path, parsed.query, ""))

def _json_object(response: ResponseLike) -> Mapping[str, Any]:
    try:
        payload = response.json()
    except Exception as error:
        raise PinAuthError(
            f"PIN endpoint вернул некорректный JSON (HTTP {response.status_code})",
            code="invalid_json",
            status_code=response.status_code,
        ) from error
    if not isinstance(payload, Mapping):
        raise PinAuthError(
            "PIN endpoint должен вернуть JSON object",
            code="invalid_json",
            status_code=response.status_code,
        )
    return payload

def _required_object(payload: Mapping[str, Any], key: str) -> Mapping[str, Any]:
    value = payload.get(key)
    if not isinstance(value, Mapping):
        raise PinAuthError(f"Auth endpoint не вернул {key}", code="invalid_primary_auth_state")
    return value

def _optional_auth_token(payload: Mapping[str, Any]) -> str | None:
    value = payload.get("token")
    if value is None:
        return None
    if not isinstance(value, str) or not value or len(value) > 8192 or _has_controls(value):
        raise PinAuthError("Сервер вернул некорректный auth token", code="invalid_auth_token")
    return value

def _required_auth_token(payload: Mapping[str, Any]) -> str:
    token = _optional_auth_token(payload)
    if token is None:
        raise PinAuthError("Auth challenge не содержит token", code="missing_auth_token")
    return token

def _verify_primary_proof(srp: PinSrp, payload: Mapping[str, Any]) -> None:
    proof = _required_object(payload, "srpInfo").get("srp_R")
    if not isinstance(proof, str) or not srp.verify_server_proof(proof):
        raise PinAuthError(
            "Сервер не подтвердил login SRP-доказательство",
            code="invalid_server_proof",
        )

def _verify_optional_primary_proof(srp: PinSrp, payload: Mapping[str, Any]) -> None:
    info = payload.get("srpInfo")
    if not isinstance(info, Mapping) or "srp_R" not in info:
        return
    _verify_primary_proof(srp, payload)

def _coerce_nonnegative_int(value: Any) -> int | None:
    if type(value) is int and value >= 0:
        return value
    if isinstance(value, str) and value.isascii() and value.isdigit():
        return int(value)
    return None

def _captcha_url(payload: Any, key: str, auth_base: str) -> str | None:
    if not isinstance(payload, Mapping) or not isinstance(payload.get(key), str):
        return None
    try:
        raw = payload[key]
        target = raw if _online_url(raw) else f"{auth_base.rstrip('/')}/{raw.lstrip('/')}"
        target = _safe_online_url(target, base=auth_base + "/")
        separator = "&" if "?" in target else "?"
        return f"{target}{separator}noc={time.time_ns() // 1_000_000}"
    except PinAuthError:
        return None

def _otp_required(confirm_info: Mapping[str, Any]) -> PinOtpRequired:
    return PinOtpRequired(
        lifetime=_optional_nonnegative_int(confirm_info, "lifetime"),
        remaining_attempts=_optional_nonnegative_int(confirm_info, "remainingAttempts"),
    )

def _optional_nonnegative_int(payload: Mapping[str, Any] | None, key: str) -> int | None:
    if not isinstance(payload, Mapping) or key not in payload:
        return None
    value = payload[key]
    return value if type(value) is int and value >= 0 else None

def _required_hex(payload: Mapping[str, Any], key: str) -> str:
    value = payload.get(key)
    if not isinstance(value, str) or _HEX.fullmatch(value) is None:
        raise PinAuthError(
            f"PIN endpoint не вернул корректный {key}",
            code="invalid_srp_challenge",
        )
    return value

def _validate_pin(pin: str, length: int) -> None:
    if (
        not isinstance(pin, str)
        or len(pin) != length
        or not pin.isascii()
        or not pin.isdigit()
    ):
        raise ValueError(f"PIN должен состоять ровно из {length} ASCII-цифр")

def _validate_deviceprint(value: str) -> str:
    if not isinstance(value, str) or not 1 <= len(value) <= 64 * 1024 or _has_controls(value):
        raise ValueError("deviceprint должен быть непустой строкой без control characters")
    return value

def _validate_short_code(value: str, name: str) -> str:
    if not isinstance(value, str) or not 1 <= len(value) <= 32 or _has_controls(value):
        raise ValueError(f"{name} должен быть строкой длиной от 1 до 32 символов")
    return value

def _validate_credential(value: str, name: str, max_length: int) -> str:
    if (
        not isinstance(value, str)
        or not value
        or len(value) > max_length
        or _has_controls(value)
    ):
        raise ValueError(f"{name} должен быть непустой строкой безопасной длины")
    return value

def _mgf1(seed: bytes, length: int) -> bytes:
    result = bytearray()
    for counter in range((length + sha1().digest_size - 1) // sha1().digest_size):
        result.extend(sha1(seed + counter.to_bytes(4, "big")).digest())
    return bytes(result[:length])

def _xor_bytes(left: bytes, right: bytes) -> bytes:
    if len(left) != len(right):
        raise ValueError("RSA-OAEP mask length mismatch")
    return bytes(a ^ b for a, b in zip(left, right, strict=True))

def _rsa_public_numbers(public_key_body: str) -> tuple[int, int]:
    if not isinstance(public_key_body, str) or not public_key_body:
        raise ValueError("RSA public key отсутствует")
    try:
        der = base64.b64decode("".join(public_key_body.split()), validate=True)
    except (ValueError, binascii.Error) as error:
        raise ValueError("RSA public key не является Base64 DER") from error
    outer, end = _der_value(der, 0, 0x30)
    if end != len(der) or not outer:
        raise ValueError("некорректный RSA public key DER")
    if outer[0] == 0x30:  # SubjectPublicKeyInfo
        algorithm, offset = _der_value(outer, 0, 0x30)
        if b"\x06\x09\x2a\x86\x48\x86\xf7\x0d\x01\x01\x01" not in algorithm:
            raise ValueError("public key algorithm is not rsaEncryption")
        bit_string, offset = _der_value(outer, offset, 0x03)
        if offset != len(outer) or not bit_string or bit_string[0] != 0:
            raise ValueError("некорректный RSA SubjectPublicKeyInfo")
        rsa, rsa_end = _der_value(bit_string, 1, 0x30)
        if rsa_end != len(bit_string):
            raise ValueError("лишние данные RSA public key")
    else:  # PKCS#1 RSAPublicKey
        rsa = outer
    modulus_raw, offset = _der_value(rsa, 0, 0x02)
    exponent_raw, offset = _der_value(rsa, offset, 0x02)
    if offset != len(rsa):
        raise ValueError("лишние данные RSA public key")
    modulus = _positive_der_integer(modulus_raw)
    exponent = _positive_der_integer(exponent_raw)
    if modulus.bit_length() < 2048 or exponent < 3 or exponent % 2 == 0:
        raise ValueError("небезопасный RSA public key")
    return modulus, exponent

def _der_value(data: bytes, offset: int, expected_tag: int) -> tuple[bytes, int]:
    if offset >= len(data) or data[offset] != expected_tag:
        raise ValueError("неожиданный ASN.1 tag")
    offset += 1
    if offset >= len(data):
        raise ValueError("обрезанная ASN.1 length")
    first = data[offset]
    offset += 1
    if first & 0x80:
        count = first & 0x7F
        if count == 0 or count > 4 or offset + count > len(data):
            raise ValueError("некорректная ASN.1 length")
        length_bytes = data[offset:offset + count]
        if length_bytes[0] == 0:
            raise ValueError("non-minimal ASN.1 length")
        length = int.from_bytes(length_bytes, "big")
        offset += count
        if length < 128:
            raise ValueError("non-minimal ASN.1 length")
    else:
        length = first
    end = offset + length
    if end > len(data):
        raise ValueError("обрезанное ASN.1 value")
    return data[offset:end], end

def _positive_der_integer(value: bytes) -> int:
    if not value or value[0] & 0x80:
        raise ValueError("ASN.1 INTEGER должен быть положительным")
    if len(value) > 1 and value[0] == 0 and not value[1] & 0x80:
        raise ValueError("non-minimal ASN.1 INTEGER")
    result = int.from_bytes(value, "big")
    if result <= 0:
        raise ValueError("ASN.1 INTEGER должен быть положительным")
    return result

def _cookie_http_only(cookie: Any) -> bool:
    for key in ("HttpOnly", "http_only"):
        value = cookie.get_nonstandard_attr(key, None)
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() == "true"
    return False

def _header(headers: Mapping[str, str], name: str) -> str | None:
    target = name.lower()
    for raw_name, value in headers.items():
        if str(raw_name).lower() == target and isinstance(value, str):
            return value
    return None

def _rq_uid() -> str:
    raw = secrets.token_hex(16)
    return f"{raw[:8]}-{raw[8:12]}-{raw[12:16]}-{raw[16:20]}-{raw[20:]}"

def _hex_int(name: str, value: str) -> int:
    if not isinstance(value, str) or _HEX.fullmatch(value) is None:
        raise ValueError(f"{name} должен быть непустым hexadecimal")
    return int(value, 16)

def _int_bytes(value: int) -> bytes:
    if value < 0:
        raise ValueError("negative SRP integer")
    return value.to_bytes(max(1, (value.bit_length() + 7) // 8), "big")

def _hash(*parts: bytes) -> bytes:
    digest = sha512()
    for part in parts:
        digest.update(part)
    return digest.digest()

async def page(
        self,
        *,
        resource: str | None = None,
        offset: int = 0,
        limit: int = 30,
        from_: date | datetime | None = None,
        to: date | datetime | None = None,
    ) -> OperationsPage:
        if resource is not None and not RESOURCE.fullmatch(resource):
            raise ValueError(
                "resource должен иметь вид card:<id>, ct-account:<id> или account:<id>"
            )
        if offset < 0 or not 1 <= limit <= 100:
            raise ValueError("offset >= 0, limit от 1 до 100")
        if from_ and to and _request_moment(from_) > _request_moment(to, end=True):
            raise ValueError("from_ должен быть не позже to")
        if from_ is None and to is None:
            from_ = _default_from()

        body: dict[str, Any] = {
            "paginationOffset": offset,
            "paginationSize": limit + 1,
            "showHidden": False,
            "showNotTransactionBonuses": True,
            "showOpenBanking": True,
        }
        if from_:
            body["from"] = _request_datetime(from_)
        if to:
            body["to"] = _request_datetime(to, end=True)
        if resource:
            body["usedResource"] = [resource]

        payload = await self._client._post(OPERATIONS_PATH, body)
        operations = parse_operations(payload, [resource] if resource else [])
        if any(not operation.id for operation in operations):
            raise ApiError("операция без обязательного uohId; история не может быть собрана без потерь")
        has_next = len(operations) > limit
        return OperationsPage(
            tuple(operations[:limit]),
            offset + limit if has_next else None,
        )

async def details(self, uoh_id: str) -> OperationDetail:
        """Full detail of one operation, addressed by its ``uohId`` (from ``list``/``page``)."""
        if not isinstance(uoh_id, str) or not re.fullmatch(r"[A-Za-z0-9_-]{1,128}", uoh_id):
            raise ValueError("uoh_id: непустой идентификатор операции (uohId)")
        payload = await self._client._post(OPERATION_DETAILS_PATH, {"uohId": uoh_id})
        return parse_operation_details(payload)

async def rename(self, card_id: str | int, name: str) -> None:
        product_id = _numeric_product_id(card_id)
        _validate_text(name, "name", allow_empty=False)
        if not _CARD_NAME.fullmatch(name):
            raise ValueError(
                "name: максимум 56 символов; разрешены буквы, цифры, пробел, '-', ',' и '.'"
            )
        try:
            await self._client._mutate(
                CHANGE_PRODUCT_NAME_PATH,
                {"id": product_id, "name": name, "type": "card"},
                query={},
                page_id=f"/app/cards/details/{product_id}",
            )
        except ApiRejected:
            raise
        except (ApiError, AuthenticationExpired, TransportError) as error:
            raise MutationUncertain(
                "результат переименования неизвестен; сначала перечитайте список карт"
            ) from error

async def amounts(
        self,
        *,
        from_: date | datetime,
        to: date | datetime,
        income_type: str = "outcome",
        between_own: bool = True,
        open_banking: bool = False,
        show_categories: bool = True,
        show_products: bool = True,
    ) -> PfmAmounts:
        """Category totals for a period. ``income_type`` is 'outcome' (spending) or 'income'."""
        if income_type not in ("income", "outcome"):
            raise ValueError("income_type: 'income' или 'outcome'")
        if _request_moment(from_) > _request_moment(to, end=True):
            raise ValueError("from_ должен быть не позже to")
        body: dict[str, Any] = {
            "filter": {
                "from": _iso_moscow(from_),
                "to": _iso_moscow(to, end=True),
                "incomeType": income_type,
                "betweenOwnFilter": "on" if between_own else "off",
                "openBankingFilter": "on" if open_banking else "off",
                "productFilters": [
                    {"type": "CARD", "filter": "custom"},
                    {"type": "CT_ACCOUNT", "filter": "custom"},
                    {"type": "MANUAL", "filter": "custom"},
                ],
            },
            "display": {
                "showCategoryAmounts": show_categories,
                "showProductAmounts": show_products,
            },
        }
        payload = await self._client._post(PFM_AMOUNTS_PATH, body)
        return parse_pfm_amounts(payload)

def export(self, path: Path | None = None) -> SessionBundle:
        bundle = self._client.export_session()
        if path is not None:
            bundle.save(path)
        return bundle

def credentials(self) -> SberCredentials:
        """Return current rotated auth values without writing them to disk."""
        return self._client.export_credentials()

def _mapping(value: Any, name: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ApiError(f"{name}: ожидался JSON object")
    return value

def _numeric_product_id(value: str | int) -> int:
    if isinstance(value, bool):
        raise TypeError("card_id должен быть положительным числовым ID")
    text = str(value)
    if not text.isdigit() or not 1 <= len(text) <= 16:
        raise ValueError("card_id должен быть положительным числовым ID")
    product_id = int(text)
    if not 0 < product_id <= 9_007_199_254_740_991:
        raise ValueError("card_id должен быть положительным JS-safe числовым ID")
    return product_id

def _validate_text(value: str, name: str, *, allow_empty: bool) -> None:
    if not isinstance(value, str):
        raise TypeError(f"{name} должен быть строкой")
    if not allow_empty and not value.strip():
        raise ValueError(f"{name} не должен быть пустым")
    if any(ord(char) < 0x20 or ord(char) == 0x7F for char in value):
        raise ValueError(f"{name} не должен содержать control characters")

def _workflow_pid(value: Any) -> str:
    if not isinstance(value, str) or not _WORKFLOW_PID.fullmatch(value):
        raise ApiError("workflow вернул некорректный pid")
    return value

def _workflow_body(
    payload: Mapping[str, Any],
    *,
    result: str,
    pid: str | None = None,
    flow: str | None = None,
    state: str | None = None,
) -> Mapping[str, Any]:
    body = _mapping(payload.get("body"), "body")
    expected = {"result": result, "pid": pid, "flow": flow, "state": state}
    for key, value in expected.items():
        if value is not None and body.get(key) != value:
            raise ApiError(f"workflow: ожидалось {key}={value!r}")
    return body

def _transfer_resources(
    references: Mapping[str, Any],
    name: str,
) -> tuple[TransferResource, ...]:
    reference = _mapping(references.get(name), f"references.{name}")
    items = reference.get("items")
    if not isinstance(items, list):
        raise ApiError(f"references.{name}.items: ожидался JSON array")
    result: list[TransferResource] = []
    for index, item in enumerate(items):
        item = _mapping(item, f"references.{name}.items[{index}]")
        resource_id = item.get("value")
        if not isinstance(resource_id, str) or not _TRANSFER_RESOURCE.fullmatch(resource_id):
            raise ApiError(f"references.{name}.items[{index}]: некорректный resource ID")
        properties = _mapping(
            item.get("properties"),
            f"references.{name}.items[{index}].properties",
        )
        result.append(TransferResource(
            id=resource_id,
            kind=str(properties.get("type") or ""),
            # _text redacts an embedded PAN, like every other server-supplied label.
            name=_text(properties.get("name") or item.get("title") or ""),
            currency=str(properties.get("currency") or ""),
        ))
    return tuple(result)

def _selected_resource(
    value: str,
    resources: tuple[TransferResource, ...],
    name: str,
) -> TransferResource:
    if not isinstance(value, str) or not _TRANSFER_RESOURCE.fullmatch(value):
        raise ValueError(f"{name} должен быть ID из transfers.start()")
    resource = next((item for item in resources if item.id == value), None)
    if resource is None:
        raise ValueError(f"{name} отсутствует в references ответа transfers.start()")
    return resource

def _workflow_url(body: Mapping[str, Any], expected_path: str) -> None:
    url = body.get("url")
    if url != expected_path:
        raise ApiError(f"workflow вернул неожиданный внешний путь вместо {expected_path}")

def _has_done_marker(output: Any) -> bool:
    if not isinstance(output, Mapping) or not isinstance(output.get("screens"), list):
        return False
    for screen in output["screens"]:
        if not isinstance(screen, Mapping) or not isinstance(screen.get("header"), list):
            continue
        for item in screen["header"]:
            properties = item.get("properties") if isinstance(item, Mapping) else None
            if isinstance(properties, Mapping) and properties.get("level") == "done":
                return True
    return False

def __post_init__(self) -> None:
        if not all(isinstance(value, str) for value in (self.name, self.value, self.domain, self.path)):
            raise ValueError("cookie name/value/domain/path должны быть строками")
        if not all(type(value) is bool for value in (self.secure, self.http_only, self.host_only)):
            raise ValueError("cookie secure/http_only/host_only должны быть bool")
        canonical_domain = self.domain.lstrip(".").lower().rstrip(".")
        object.__setattr__(self, "domain", canonical_domain)
        if len(self.name) > 256 or len(self.value) > 4096 or len(canonical_domain) > 253:
            raise ValueError("cookie name/value/domain превышает допустимый размер")
        if len(self.path) > 2048:
            raise ValueError("cookie path превышает допустимый размер")
        if not self.path.startswith("/") or any(ord(char) < 0x20 or ord(char) == 0x7F for char in self.path):
            raise ValueError("cookie path должен начинаться с / и не содержать control characters")
        if self.expires is not None and type(self.expires) is not int:
            raise ValueError("cookie expires должен быть целым Unix timestamp или null")
        if self.expires is not None and self.expires <= 0:
            raise ValueError("cookie expires должен быть положительным Unix timestamp")
        if self.same_site is not None and self.same_site not in ("Strict", "Lax", "None"):
            raise ValueError("cookie same_site должен быть Strict, Lax, None или null")
        if _record_to_cookie(self) is None:
            raise ValueError(f"некорректная cookie metadata: {self.name!r}")
        if self.name.startswith("__Secure-") and not self.secure:
            raise ValueError("cookie с префиксом __Secure- обязана иметь Secure")
        if self.name.startswith("__Host-") and (not self.secure or not self.host_only or self.path != "/"):
            raise ValueError("cookie с префиксом __Host- обязана быть Secure, host-only и path=/")

def __repr__(self) -> str:
        return (
            f"CookieRecord(name={self.name!r}, value=<redacted>, "
            f"domain={self.domain!r}, path={self.path!r})"
        )

def __post_init__(self) -> None:
        if len(self.headers) > MAX_BROWSER_HEADERS:
            raise ValueError("слишком много браузерных заголовков")
        normalized: list[tuple[str, str]] = []
        seen: set[str] = set()
        for raw_name, raw_value in self.headers:
            name = str(raw_name).lower()
            value = str(raw_value)
            if name not in OBSERVED_HEADER_NAMES or name in seen:
                raise ValueError(f"браузерный заголовок не разрешён: {name!r}")
            if "\r" in value or "\n" in value:
                raise ValueError(f"некорректное значение заголовка: {name!r}")
            if len(value) > 8192:
                raise ValueError(f"значение заголовка слишком велико: {name!r}")
            seen.add(name)
            normalized.append((name, value))
        object.__setattr__(self, "headers", tuple(normalized))

def from_har(cls, path: Path, *, require_private: bool = True) -> "BrowserProfile":
        """Import only observed browser identity headers; no cookies or responses."""
        if require_private:
            _validate_private_source(path, "HAR")
        try:
            inspection, _ = inspect_har(path)
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
            raise MissingSession("HAR не удалось разобрать") from error
        return cls.from_mapping(inspection.observed_headers)

def __post_init__(self) -> None:
        for cookie_name, value in self._items():
            if not isinstance(value, str) or not value:
                raise ValueError(f"{cookie_name} должен быть непустой строкой")
            CookieRecord(
                name=cookie_name,
                value=value,
                domain=AUTH_COOKIE_DOMAIN,
                path="/",
                secure=True,
                http_only=True,
                host_only=False,
            )

def from_bundle(cls, bundle: "SessionBundle") -> "SberCredentials":
        """Extract only the two required cross-subdomain auth cookies."""
        if not isinstance(bundle, SessionBundle):
            raise TypeError("bundle должен быть SessionBundle")
        values: dict[str, str] = {}
        auth_names = {"UFS-SESSION", "UFS-TOKEN"}
        for cookie in bundle.cookies:
            if (
                cookie.name in auth_names
                and cookie.domain == AUTH_COOKIE_DOMAIN
                and cookie.path == "/"
                and cookie.secure
                and not cookie.host_only
            ):
                if cookie.name in values:
                    raise MissingSession(f"неоднозначная auth cookie: {cookie.name}")
                values[cookie.name] = cookie.value
        missing = sorted(auth_names - values.keys())
        if missing:
            raise MissingSession(f"не хватает auth cookies: {', '.join(missing)}")
        return cls(
            ufs_session=values["UFS-SESSION"],
            ufs_token=values["UFS-TOKEN"],
        )

def _items(self) -> tuple[tuple[str, str], ...]:
        return (
            ("UFS-SESSION", self.ufs_session),
            ("UFS-TOKEN", self.ufs_token),
        )

def __post_init__(self) -> None:
        if type(self.schema_version) is not int or self.schema_version != SESSION_SCHEMA_VERSION:
            raise ValueError(f"неподдерживаемая версия SessionBundle: {self.schema_version}")
        if not isinstance(self.api_base, str) or not isinstance(self.web_base, str):
            raise ValueError("api_base и web_base должны быть строками")
        if not isinstance(self.browser, BrowserProfile):
            raise ValueError("browser должен быть BrowserProfile")
        if self.deviceprint is not None:
            _validate_deviceprint(self.deviceprint)
        if self.antifraud_deviceprint is not None:
            _validate_antifraud_deviceprint(self.antifraud_deviceprint)
        if self.captured_at is not None and not isinstance(self.captured_at, str):
            raise ValueError("captured_at должен быть строкой или null")
        if not _online_url(self.api_base) or not _online_url(self.web_base):
            raise ValueError("SessionBundle разрешает только HTTPS-хосты online.sberbank.ru")
        object.__setattr__(self, "api_base", self.api_base.rstrip("/"))
        object.__setattr__(self, "web_base", self.web_base.rstrip("/"))
        object.__setattr__(self, "cookies", tuple(self.cookies))
        if len(self.cookies) > MAX_COOKIES:
            raise MissingSession("SessionBundle содержит слишком много cookies")
        keys = [(cookie.name, cookie.domain, cookie.path) for cookie in self.cookies]
        if len(keys) != len(set(keys)):
            raise ValueError("SessionBundle содержит дублирующиеся cookie name/domain/path")

def __repr__(self) -> str:
        return (
            f"SessionBundle(api_base={self.api_base!r}, web_base={self.web_base!r}, "
            f"cookies={len(self.cookies)}, browser={self.browser!r})"
        )

def from_files(
        cls,
        har: Path,
        cookies: Path | None = None,
        *,
        require_private_har: bool = True,
        require_private_cookies: bool = True,
    ) -> "SessionBundle":
        """Import current hosts/profile from HAR and credentials from HAR/cookies.txt."""
