def with_antifraud_from_har(
        self,
        path: Path,
        *,
        require_private: bool = True,
    ) -> "SessionBundle":
        """Attach the exact opaque window.bfd.getEncodedData() value captured by Chrome."""
        if require_private:
            _validate_private_source(path, "HAR")
        try:
            inspection, _ = inspect_har(path)
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
