def load(cls, path: Path, *, require_private: bool = True) -> "SessionBundle":
        try:
            raw = _read_session_file(path, require_private=require_private)
            payload = json.loads(raw.decode("utf-8"), object_pairs_hook=_unique_object)
        except InsecureSessionFile:
            raise
        except (OSError, UnicodeError, json.JSONDecodeError, ValueError) as error:
            raise MissingSession("SessionBundle не является корректным UTF-8 JSON") from error
        if not isinstance(payload, Mapping) or payload.get("schema") != SESSION_SCHEMA:
            raise MissingSession("неизвестная схема SessionBundle")
        try:
            version = _required_int(payload, "version")
            if version == 1:
                _exact_keys(
                    payload,
                    {"schema", "version", "api_base", "web_base", "captured_at", "browser", "cookies"},
                    "SessionBundle",
                )
                deviceprint = None
                antifraud_deviceprint = None
            elif version == 2:
                _exact_keys(
                    payload,
                    {
                        "schema",
                        "version",
                        "api_base",
                        "web_base",
                        "captured_at",
                        "browser",
                        "deviceprint",
                        "cookies",
                    },
                    "SessionBundle",
                )
                deviceprint = _nullable_str(payload, "deviceprint")
                antifraud_deviceprint = None
            elif version in (3, SESSION_SCHEMA_VERSION):
                _exact_keys(
                    payload,
                    {
                        "schema",
                        "version",
                        "api_base",
                        "web_base",
                        "captured_at",
                        "browser",
                        "deviceprint",
                        "antifraud_deviceprint",
                        "cookies",
                    },
                    "SessionBundle",
                )
                deviceprint = _nullable_str(payload, "deviceprint")
                antifraud_deviceprint = _nullable_str(payload, "antifraud_deviceprint")
            else:
                raise ValueError("unsupported SessionBundle version")
            browser_payload = payload.get("browser", {})
            if not isinstance(browser_payload, Mapping):
                raise TypeError("browser")
            _exact_keys(browser_payload, {"headers"}, "browser")
            headers_payload = browser_payload.get("headers", []) if isinstance(browser_payload, Mapping) else []
            if not isinstance(headers_payload, list):
                raise TypeError("browser headers")
            for item in headers_payload:
                if not isinstance(item, Mapping):
                    raise TypeError("browser header")
                _exact_keys(item, {"name", "value"}, "browser header")
            headers = tuple(
                (_required_str(item, "name"), _required_str(item, "value"))
                for item in headers_payload
                if isinstance(item, Mapping)
            )
            if len(headers) != len(headers_payload):
                raise TypeError("browser headers")
            raw_cookies = payload.get("cookies")
            if not isinstance(raw_cookies, list):
                raise TypeError("cookies")
            for item in raw_cookies:
                if not isinstance(item, Mapping):
                    raise TypeError("cookie record")
                _exact_keys(
                    item,
                    {"name", "value", "domain", "path", "secure", "http_only", "host_only", "expires"}
                    | ({"same_site"} if version == SESSION_SCHEMA_VERSION else set()),
                    "cookie record",
                )
            records = tuple(
                CookieRecord(
                    name=_required_str(item, "name"),
                    value=_required_str(item, "value"),
                    domain=_required_str(item, "domain"),
                    path=_required_str(item, "path"),
                    secure=_required_bool(item, "secure"),
                    http_only=_required_bool(item, "http_only"),
                    host_only=_required_bool(item, "host_only"),
                    expires=_nullable_int(item, "expires"),
                    same_site=_nullable_str(item, "same_site") if version == SESSION_SCHEMA_VERSION else None,
                )
                for item in raw_cookies
                if isinstance(item, Mapping)
            )
            if len(records) != len(raw_cookies):
                raise TypeError("cookie record")
            return cls(
                api_base=_required_str(payload, "api_base"),
                web_base=_required_str(payload, "web_base"),
                cookies=records,
                browser=BrowserProfile(headers),
                deviceprint=deviceprint,
                antifraud_deviceprint=antifraud_deviceprint,
                captured_at=_nullable_str(payload, "captured_at"),
                schema_version=SESSION_SCHEMA_VERSION,
            )
        except (KeyError, TypeError, ValueError) as error:
            raise MissingSession("SessionBundle содержит некорректные поля") from error

def save(self, path: Path) -> None:
        """Atomically write secret state as a mode-0600 JSON file."""
        _write_session_file(path, self._secret_payload())

def to_seed(self, *, require_ready: bool = True) -> SessionSeed:
        jar = CookieJar()
        for record in self.cookies:
            cookie = _record_to_cookie(record)
            if cookie is None:
                raise MissingSession(f"не удалось восстановить cookie: {record.name!r}")
            _apply_cookie(jar, cookie)
        jar.clear_expired_cookies()
        if require_ready and not any(True for _ in jar):
            raise MissingSession("все cookies в SessionBundle истекли")
        if require_ready and not _session_cookies_ready(jar, self.api_base, self.web_base):
            raise MissingSession("cookies SessionBundle не подходят одновременно для API и warm-up")
        return SessionSeed(self.api_base, self.web_base, jar, self.browser.as_dict())

def with_cookie_jar(self, jar: CookieJar) -> "SessionBundle":
        """Return an updated immutable bundle after transport Set-Cookie processing."""
        previous = {(cookie.name, cookie.domain, cookie.path): cookie for cookie in self.cookies}
        records: dict[tuple[str, str, str], CookieRecord] = {}
        for cookie in jar:
            if cookie.is_expired():
                continue
            record = _cookie_to_record(cookie)
            key = (record.name, record.domain, record.path)
            old = previous.get(key)
            if old and old.http_only and not record.http_only:
                record = replace(record, http_only=True)
            records[key] = record
        return replace(
            self,
            cookies=tuple(records.values()),
            captured_at=datetime.now(timezone.utc).isoformat(),
        )

def _required_bool(item: Mapping[str, Any], key: str) -> bool:
    value = item.get(key)
    if type(value) is not bool:
        raise TypeError(key)
    return value

def _validate_deviceprint(value: str) -> str:
    if (
        not isinstance(value, str)
        or not 1 <= len(value) <= 64 * 1024
        or any(ord(char) < 0x20 or ord(char) == 0x7F for char in value)
    ):
        raise ValueError("deviceprint должен быть непустой строкой без control characters")
    return value

def _validate_antifraud_deviceprint(value: str) -> str:
    if (
        not isinstance(value, str)
        or not 1 <= len(value) <= 64 * 1024
        or any(ord(char) < 0x20 or ord(char) == 0x7F for char in value)
    ):
        raise ValueError(
            "antifraud_deviceprint должен быть непустой строкой без control characters"
        )
    return value

def _browser_cookie_expiry(item: Mapping[str, Any]) -> int | None:
    if item.get("session") is True or "expirationDate" not in item:
        return None
    value = item["expirationDate"]
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise TypeError("expirationDate")
    expires = int(value)
    if expires <= 0:
        raise ValueError("expirationDate")
    return expires

def _browser_same_site(value: Any) -> str | None:
    if value is None:
        return None
    choices = {"strict": "Strict", "lax": "Lax", "none": "None", "no_restriction": "None", "unspecified": None}
    if not isinstance(value, str) or value.lower() not in choices:
        raise ValueError("cookie same_site не поддерживается")
    return choices[value.lower()]

def _exact_keys(item: Mapping[str, Any], allowed: set[str], name: str) -> None:
    if set(item) != allowed:
        raise TypeError(f"{name}: набор полей не соответствует schema")

def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ValueError(f"duplicate JSON key: {key}")
        result[key] = value
    return result

def _validate_session_stat(info: os.stat_result, *, require_private: bool) -> None:
    if not stat.S_ISREG(info.st_mode):
        raise InsecureSessionFile("SessionBundle должен быть обычным файлом, не symlink")
    if info.st_size > MAX_SESSION_FILE_BYTES:
        raise MissingSession("SessionBundle неожиданно велик")
    getuid = getattr(os, "getuid", None)
    if require_private and getuid is None:
        raise InsecureSessionFile("платформа не позволяет надёжно проверить владельца SessionBundle")
    wrong_owner = getuid is not None and info.st_uid != getuid()
    if require_private and (wrong_owner or stat.S_IMODE(info.st_mode) & 0o077):
        raise InsecureSessionFile("SessionBundle имеет чужого владельца или доступен группе/остальным; нужен mode 0600")

def _validate_private_source(path: Path, label: str) -> None:
    try:
        info = path.lstat()
    except FileNotFoundError as error:
        raise MissingSession(f"{label} не найден: {path}") from error
    getuid = getattr(os, "getuid", None)
    if getuid is None:
        raise InsecureSessionFile(f"платформа не позволяет надёжно проверить владельца {label}")
    wrong_owner = getuid is not None and info.st_uid != getuid()
    if not stat.S_ISREG(info.st_mode) or wrong_owner or stat.S_IMODE(info.st_mode) & 0o077:
        raise InsecureSessionFile(f"{label} должен быть обычным файлом владельца с mode 0600: {path}")

def _read_session_file(path: Path, *, require_private: bool) -> bytes:
    nofollow = getattr(os, "O_NOFOLLOW", None)
    before: os.stat_result | None = None
    if nofollow is None:
        try:
            before = path.lstat()
        except FileNotFoundError as error:
            raise MissingSession(f"SessionBundle не найден: {path}") from error
        if stat.S_ISLNK(before.st_mode) or not stat.S_ISREG(before.st_mode):
            raise InsecureSessionFile("SessionBundle должен быть обычным файлом, не symlink")
    flags = os.O_RDONLY | getattr(os, "O_CLOEXEC", 0) | (nofollow or 0)
    try:
        descriptor = os.open(path, flags)
    except FileNotFoundError as error:
        raise MissingSession(f"SessionBundle не найден: {path}") from error
    except OSError as error:
        raise InsecureSessionFile(f"SessionBundle нельзя безопасно открыть: {path}") from error
    try:
        opened = os.fstat(descriptor)
        if before is not None and (before.st_dev, before.st_ino) != (opened.st_dev, opened.st_ino):
            raise InsecureSessionFile("SessionBundle был подменён во время открытия")
        _validate_session_stat(opened, require_private=require_private)
        with os.fdopen(descriptor, "rb") as file:
            descriptor = -1
            raw = file.read(MAX_SESSION_FILE_BYTES + 1)
        if len(raw) > MAX_SESSION_FILE_BYTES:
            raise MissingSession("SessionBundle неожиданно велик")
        return raw
    finally:
        if descriptor >= 0:
            os.close(descriptor)

def _required_str(item: Mapping[str, Any], key: str) -> str:
    value = item.get(key)
    if not isinstance(value, str):
        raise TypeError(key)
    return value

def _nullable_str(item: Mapping[str, Any], key: str) -> str | None:
    value = item.get(key)
    if value is not None and not isinstance(value, str):
        raise TypeError(key)
    return value

def _required_int(item: Mapping[str, Any], key: str) -> int:
    value = item.get(key)
    if type(value) is not int:
        raise TypeError(key)
    return value

def _nullable_int(item: Mapping[str, Any], key: str) -> int | None:
    if key not in item:
        raise TypeError(key)
    value = item[key]
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, int):
        raise TypeError("expires")
    return value

