def _write_session_file(path: Path, payload: Mapping[str, Any]) -> None:
    descriptor, temporary = tempfile.mkstemp(prefix=f".{path.name}.", suffix=".tmp", dir=path.parent)
    replaced = False
    try:
        os.fchmod(descriptor, 0o600)
        with os.fdopen(descriptor, "w", encoding="utf-8") as file:
            descriptor = -1
            json.dump(payload, file, ensure_ascii=False, indent=2)
            file.write("\n")
            file.flush()
            os.fsync(file.fileno())
            _validate_session_stat(os.fstat(file.fileno()), require_private=True)
        os.replace(temporary, path)
        replaced = True
        _validate_session_stat(path.lstat(), require_private=True)
    except BaseException:
        if descriptor >= 0:
            os.close(descriptor)
        try:
            if replaced:
                path.unlink()
            else:
                os.unlink(temporary)
        except FileNotFoundError:
            pass
        raise

def _cookie_same_site(cookie: Cookie) -> Any:
    """Stdlib preserves extension-attribute spelling; HTTP names ignore case."""
    rest: Mapping[str, Any] = cast(Any, cookie)._rest
    for name, value in reversed(tuple(rest.items())):
        if name.lower() == "samesite":
            return value
    return None

def _cookie_http_only(cookie: Cookie) -> bool:
    """Accept stdlib and curl_cffi spellings without treating string 'False' as true."""
    for key in ("HttpOnly", "http_only"):
        value = cookie.get_nonstandard_attr(key, None)
        if isinstance(value, bool):
            return value
        if isinstance(value, str):
            return value.lower() == "true"
    return False

def __init__(self) -> None:
        super().__init__()
        self.deleted: set[tuple[str, str, str]] = set()

def clear(self, domain: str | None = None, path: str | None = None, name: str | None = None) -> None:
        if domain is not None and path is not None and name is not None:
            self.deleted.add((name, domain.lstrip(".").lower(), path or "/"))
        super().clear(domain, path, name)

def _parse_response(
        self, curl: Any, buffer: Any, header_buffer: Any,
        default_encoding: Any, discard_cookies: bool,
    ) -> Any:
        previous = {_cookie_key(cookie): _cookie_same_site(cookie) for cookie in self.cookies.jar}
        response = super()._parse_response(curl, buffer, header_buffer, default_encoding, discard_cookies)
        if discard_cookies or self.discard_cookies:
            return response
        # curl_cffi merges native stores; do not prune unrelated shared-jar
        # cookies that another in-flight request may have added.
        live = {_cookie_key(CurlMorsel.from_curl_format(raw).to_cookiejar_cookie()) for raw in curl.getinfo(CurlInfo.COOKIELIST)}
        message = Message()
        for header in response.headers.get_list("set-cookie"):
            message.add_header("Set-Cookie", header)
        request = Request(response.url)
        incoming = _ResponseCookieJar()
        incoming.extract_cookies(cast(Any, SimpleNamespace(info=lambda: message)), request)
        policy = DefaultCookiePolicy()
        policies = {_cookie_key(cookie): _cookie_same_site(cookie) for cookie in incoming}
        for cookie in tuple(self.cookies.jar):
            key = _cookie_key(cookie)
            if key in incoming.deleted and key not in live and policy.domain_return_ok(cookie.domain, request):
                self.cookies.jar.clear(cookie.domain, cookie.path, cookie.name)
            else:
                # Membership, not value equality: even same-value Set-Cookie
                # can deliberately reset SameSite to unspecified.
                cookie.set_nonstandard_attr("SameSite", cast(Any, policies.get(key, previous.get(key))))
        return response

async def get(
        self,
        url: str,
        *,
        accept_encoding: str,
        headers: Mapping[str, str | None] | None = None,
    ) -> ResponseLike:
        if self._closed:
            raise RuntimeError("transport уже закрыт")
        try:
            request_headers: dict[str, str | None] = {
                "Accept": "*/*",
                "Content-Type": "application/json; charset=utf-8",
                "X-Requested-With": None,
            }
            request_headers.update(headers or {})
            return await self._session.get(
                url,
                headers=request_headers,
                accept_encoding=accept_encoding,
            )
        except RequestException as error:
            raise TransportError("HTTP-запрос не выполнен") from error

async def post(
        self,
        url: str,
        *,
        json: Mapping[str, Any] | None,
        accept_encoding: str,
        headers: Mapping[str, str | None] | None = None,
    ) -> ResponseLike:
        if self._closed:
            raise RuntimeError("transport уже закрыт")
        try:
            if json is None:
                return await self._session.post(
                    url,
                    headers=dict(headers or {}),
                    accept_encoding=accept_encoding,
                )
            return await self._session.post(
                url,
                json=dict(json),
                headers=dict(headers or {}),
                accept_encoding=accept_encoding,
            )
        except RequestException as error:
            raise TransportError("HTTP-запрос не выполнен") from error

async def post_form(
        self,
        url: str,
        *,
        data: Mapping[str, str],
        accept_encoding: str,
        headers: Mapping[str, str | None] | None = None,
    ) -> ResponseLike:
        if self._closed:
            raise RuntimeError("transport уже закрыт")
        try:
            return await self._session.post(
                url,
                data=dict(data),
                headers=dict(headers or {}),
                accept_encoding=accept_encoding,
            )
        except RequestException as error:
            raise TransportError("HTTP-запрос не выполнен") from error

def _ca_bundle_path(value: str | Path | None) -> str | None:
    """Explicit trust only; never accept bool or consult environment CA settings."""
    if value is None:
        return None
    if not isinstance(value, (str, Path)) or not str(value):
        raise ValueError("ca_bundle должен быть путём к PEM CA bundle, не bool")
    try:
        path = Path(value).expanduser().resolve(strict=True)
        if not path.is_file():
            raise ValueError("CA bundle должен быть обычным файлом")
    except OSError:
        raise ValueError("CA bundle не найден или недоступен") from None
    return str(path)

def __init__(self) -> None:
        self.operations = _DemoOperations()
        self.bundle = SimpleNamespace(antifraud_deviceprint=None)

def _envelope(status: str, code: str, next_action: str, *, retryable: bool = False,
              details: dict | None = None, session_id: str | None = None,
              state: str | None = None, data: dict | None = None) -> dict:
    env: dict[str, Any] = {
        "status": status,
        "code": code,
        "message": MESSAGES.get(code, MESSAGES["internal_error"]),
        "retryable": retryable,
        "next_action": next_action,
        "details": details or {},
    }
    if session_id is not None:
        env["session_id"] = session_id
    if state is not None:
        env["state"] = state
    if data is not None:
        env["data"] = data
    return env

def err(code: str, next_action: str, *, retryable: bool = False, details: dict | None = None,
        session_id: str | None = None, state: str | None = None) -> dict:
    return _envelope("error", code, next_action, retryable=retryable, details=details,
                     session_id=session_id, state=state)

def challenge(code: str, *, details: dict, session_id: str, state: str,
              next_action: str = NA_SUBMIT) -> dict:
    return _envelope("challenge", code, next_action, details=details,
                     session_id=session_id, state=state)

def _money(m) -> dict | None:
    if m is None:
        return None
    return {"amount": format(m.amount, "f"), "currency": m.currency}

def _resource(r) -> dict | None:
    if r is None:
        return None
    return {"type": r.type, "id": r.id}

def _account_out(a) -> dict:
    return {
        "id": a.id, "kind": a.kind, "name": a.name, "last4": a.last4,
        "state": a.state, "hidden": a.hidden, "arrested": a.arrested,
        "balance": _money(a.balance),
        "operation_resource": a.operation_resource,
        "transfer_resource": a.transfer_resource,
        "card_ids": [c.id for c in a.cards],
    }

def _card_out(c) -> dict:
    return {
        "id": c.id, "name": c.name, "last4": c.last4, "type": c.type,
        "state": c.state, "hidden": c.hidden, "arrested": c.arrested,
        "is_main": c.is_main, "balance": _money(c.balance),
        "balance_source": c.balance_source, "account_id": c.account_id,
        "account_balance": _money(c.account_balance),
        "operation_resource": c.operation_resource,
        "transfer_resource": c.transfer_resource,
    }

def _safe_text(value: Any, limit: int = 200) -> str | None:
    """Redact an embedded PAN and bound length before a server string enters output."""
    if not isinstance(value, str) or not value:
        return None
    return _text(value)[:limit]

def map_error(exc: BaseException) -> dict:
    if isinstance(exc, PinOtpRequired):
        # A challenge, not an error; represented identically whether raised or returned.
        return _envelope("challenge", "otp_required", NA_SUBMIT, details={
            "expects": ["otp"],
            "expires_in_seconds": exc.lifetime,
            "remaining_attempts": exc.remaining_attempts,
            "resend_available": True,
        })
    if isinstance(exc, PinCaptchaRequired):
        rejected = exc.code == "invalid_captcha"
        return _envelope("challenge", "captcha_rejected" if rejected else "captcha_required",
                         NA_SUBMIT, details={"expects": ["captcha_code"], "sdk_code": exc.code})
    if isinstance(exc, PinAuthError):
        return _map_pin_auth_error(exc)
    if isinstance(exc, ApiRejected):
        return err("api_rejected", NA_ABORT, details={
            "sdk_code": _safe_text(exc.code, 128), "title": _safe_text(exc.title),
            "text": _safe_text(exc.text), "uuid": _safe_text(exc.uuid, 256),
            "system": _safe_text(exc.system, 256),
        })
    if isinstance(exc, ParseError):
        return err("parse_error", NA_ABORT)  # message interpolates the value — never echo
    if isinstance(exc, ApiError):
        return err("api_unexpected", NA_ABORT)
    if isinstance(exc, MutationUncertain):
        return err("mutation_uncertain", NA_UNKNOWN, details={"phase": "sent_result_unknown"})
    if isinstance(exc, AuthenticationExpired):
        return err("session_expired", NA_REAUTH_PIN)
    if isinstance(exc, InsecureSessionFile):
        return err("secret_file_insecure", NA_FIX_SECRET,
                   details={"fix": "chmod 600 <path>; must be a regular file you own"})
    if isinstance(exc, MissingSession):
        return err("session_file_invalid", NA_FIX_SECRET)
    if isinstance(exc, TransportError):
        return err("transport_failed", NA_WAIT, retryable=True, details={"retry_after_seconds": 5})
    if isinstance(exc, SberError):
        return err("auth_protocol_unexpected", NA_RESTART)
    if isinstance(exc, (ValueError, TypeError)):
        return err("invalid_arguments", NA_FIX_ARGS)
    if isinstance(exc, OSError):
        return err("local_io_failed", NA_FIX_SECRET,
                   details={"errno_name": os.strerror(exc.errno) if exc.errno is not None else None})
    return err("internal_error", NA_ABORT, details={"exception_type": type(exc).__name__})

def _map_pin_auth_error(exc: PinAuthError) -> dict:
    code = exc.code or "unknown_pin_error"
    remaining = exc.remaining_attempts
    if code == "wrong_pin":
        nxt = NA_SUBMIT if (remaining or 0) > 1 else NA_FIX_SECRET
        return err("pin_rejected", nxt, details={"remaining_attempts": remaining})
    if code == "wrong_code":
        nxt = NA_SUBMIT if remaining != 0 else NA_ABORT
        return err("otp_rejected", nxt, details={"remaining_attempts": remaining})
    if code in _PIN_CODE_MAP:
        mcode, nxt = _PIN_CODE_MAP[code]
        return err(mcode, nxt, details={"remaining_attempts": remaining})
    if code in _PIN_WAIT:
        mcode = "otp_resend_too_early" if code == "too_early" else "bank_temporarily_unavailable"
        return err(mcode, NA_WAIT, retryable=True, details={"retry_after_seconds": _PIN_WAIT[code]})
    if code in _PIN_RESET:
        return err("auth_process_reset", NA_RESTART)
    if code in _PIN_STATE:
        return err("auth_state_invalid", NA_RESTART)
    if code in _PIN_UNSAFE:
        return err("unsafe_server_response", NA_ABORT)
    if code in _PIN_BOOTSTRAP:
        return err("auth_bootstrap_failed", NA_WAIT, retryable=True, details={"retry_after_seconds": 30})
    return err("pin_auth_failed", NA_RESTART, details={"sdk_code": _safe_text(code, 64)})

def _require_private_dir(path: Path) -> None:
    info = path.stat()
    if not stat.S_ISDIR(info.st_mode):
        raise InsecureSessionFile(f"{path} must be a directory")
    getuid = getattr(os, "getuid", None)
    if getuid is not None and info.st_uid != getuid():
        raise InsecureSessionFile(f"{path} must be owned by you")
    if stat.S_IMODE(info.st_mode) & 0o077:
        raise InsecureSessionFile(f"{path} must not be group/other accessible (chmod 700)")

def _read_secret_file(path: Path) -> str:
    raw = _read_session_file(path, require_private=True)
    return raw.decode("utf-8").rstrip("\r\n")

def _cred_path(self) -> Path:
        env = os.environ.get("SBER_MCP_CREDENTIALS")
        if env:
            return Path(env)
        specific = self.home / f"credentials-{self.profile}.json"
        return specific if specific.exists() else self.home / "credentials.json"

def _cred_json(self) -> dict:
        raw = _read_session_file(self._cred_path(), require_private=True)
        payload = json.loads(raw.decode("utf-8"))
        if not isinstance(payload, dict):
            raise MissingSession("credentials.json must be a JSON object")
        return payload

def login_password(self) -> tuple[str, str]:
        login = os.environ.get("SBER_LOGIN")
        password = os.environ.get("SBER_PASSWORD")
        if login and password:
            return login, password
        data = self._cred_json()
        login, password = data.get("login"), data.get("password")
        if not isinstance(login, str) or not login or not isinstance(password, str) or not password:
            raise MissingSession("login/password not configured")
        return login, password

def deviceprint(self) -> str:
        env = os.environ.get("SBER_DEVICEPRINT_FILE")
        if env:
            return _read_secret_file(Path(env))
        state_file = self.home / DEVICEPRINT_FILE
        if state_file.exists():                       # written by `sber-unofficial-mcp login`
            return _read_secret_file(state_file)
        data = self._cred_json()
        if data.get("deviceprint_file"):
            return _read_secret_file(Path(data["deviceprint_file"]))
        value = data.get("deviceprint")
        if not isinstance(value, str) or not value:
            raise MissingSession("deviceprint not configured")
        return value

def antifraud(self) -> str | None:
        env = os.environ.get("SBER_ANTIFRAUD_DEVICEPRINT_FILE")
        if env:
            return _read_secret_file(Path(env))
        state_file = self.home / ANTIFRAUD_FILE
        if state_file.exists():
            return _read_secret_file(state_file)
        try:
            data = self._cred_json()
        except (MissingSession, InsecureSessionFile, OSError, ValueError):
            return None
        if data.get("antifraud_deviceprint_file"):
            return _read_secret_file(Path(data["antifraud_deviceprint_file"]))
        value = data.get("antifraud_deviceprint")
        return value if isinstance(value, str) and value else None

def ufs_credentials(self) -> SberCredentials | None:
        env_s, env_t = os.environ.get("SBER_UFS_SESSION"), os.environ.get("SBER_UFS_TOKEN")
        if env_s and env_t:
            return SberCredentials(ufs_session=env_s, ufs_token=env_t)
        try:
            data = self._cred_json()
        except (MissingSession, InsecureSessionFile, OSError, ValueError):
            return None
        s, t = data.get("ufs_session"), data.get("ufs_token")
        if isinstance(s, str) and s and isinstance(t, str) and t:
            return SberCredentials(ufs_session=s, ufs_token=t)
        return None

def artifact_status(self) -> dict:
        def state(getter) -> str:
            try:
                return "configured" if getter() else "missing"
            except InsecureSessionFile:
                return "insecure_permissions"
            except (MissingSession, OSError, ValueError):
                return "missing"
        return {
            "login": state(lambda: self.login_password()[0]),
            "password": state(lambda: self.login_password()[1]),
            "deviceprint": state(self.deviceprint),
            "antifraud_deviceprint": "configured" if self.antifraud() else "missing",
            "ufs_credentials": "configured" if self.ufs_credentials() else "missing",
        }

def state(getter) -> str:
            try:
                return "configured" if getter() else "missing"
            except InsecureSessionFile:
                return "insecure_permissions"
            except (MissingSession, OSError, ValueError):
                return "missing"

def __init__(self, home: Path):
        self.home = home
        self.by_profile: dict[str, SessionState] = {}
        self.by_id: dict[str, SessionState] = {}
        self._inbox_root = home / "inbox"
        self._audit = home / "audit.jsonl"

def get(self, session_id: str) -> SessionState:
        if not SESSION_ID.fullmatch(session_id or ""):
            raise ValueError("invalid session_id")
        state = self.by_id.get(session_id)
        if state is None:
            raise _NotFound()
        return state

def resolve(self, session_id: str | None = None, profile: str = "default") -> SessionState:
        """The session a data/mutation tool should act on.

        An explicit ``session_id`` always wins (back-compat). Otherwise the active
        session is used: the one bound to ``profile``, or — when exactly one session
        exists — that one. The agent therefore never has to carry a session handle;
        it authenticates once and calls the data tools bare.
        """
        if session_id:
            return self.get(session_id)
        st = self.by_profile.get(profile)
        if st is not None:
            return st
        live = list(self.by_id.values())
        if len(live) == 1:
            return live[0]
        if not live:
            raise _NotFound()
        raise _Ambiguous([s.session_id for s in live])

def _close_inbox_fd(self, st: SessionState) -> None:
        if st.inbox_fd is not None:
            try:
                os.close(st.inbox_fd)
            except OSError:
                pass
            st.inbox_fd = None

def clear_inbox(self, st: SessionState) -> None:
        self._close_inbox_fd(st)
        session_dir = self._inbox_root / st.session_id
        if session_dir.exists():
            for f in session_dir.iterdir():
                try:
                    f.unlink()
                except OSError:
                    pass
        st.inbox_path = st.inbox_inode = None

async def close_all(self) -> None:
        for st in list(self.by_id.values()):
            await self.close(st)

async def reap_once(self) -> None:
        now = _now()
        for st in list(self.by_id.values()):
            idle = now - st.last_activity
            pending = st.state.startswith("awaiting_")
            if pending and (st.challenge_expires and now > st.challenge_expires or idle > PENDING_TTL):
                await self.close(st)
            elif st.state == "authenticated" and idle > AUTH_IDLE_TTL:
                await self.close(st)

async def reap_forever(self) -> None:
        while True:
            await asyncio.sleep(60)
            try:
                await self.reap_once()
            except Exception:
                pass

def _registry() -> Registry:
    global _REG
    if _REG is None:
        _REG = Registry(_home())
        if _demo_mode():
            _seed_demo(_REG)
    return _REG

def _apply_login_result(st: SessionState, bundle: SessionBundle | None, config: Config) -> dict:
    """Translate an AsyncPrimaryAuth/PinAuth login/confirm result into a challenge/None marker."""
    if bundle is not None:
        return {"bundle": bundle}
    # None → server wants a new PIN (primary flow, pinInfo.publicKey)
    length = getattr(getattr(st.auth, "_config", None), "pin_length", 5)
    st.state, st.challenge_code = "awaiting_pin_setup", "pin_creation_required"
    st.challenge_expires = _now() + timedelta(minutes=15)
    return {"challenge": ("pin_creation_required",
                          {"expects": ["new_pin", "new_pin_confirm"], "pin_length": length})}

def _challenge_details_from_exc(exc: PinOtpRequired | PinCaptchaRequired) -> tuple[str, str, dict]:
    if isinstance(exc, PinOtpRequired):
        return ("awaiting_otp", "otp_required", {
            "expects": ["otp"], "expires_in_seconds": exc.lifetime,
            "remaining_attempts": exc.remaining_attempts, "resend_available": True})
    rejected = exc.code == "invalid_captcha"
    return ("awaiting_captcha", "captcha_rejected" if rejected else "captcha_required",
            {"expects": ["captcha_code"]})

def _allow_writes() -> bool:
    """Writes are opt-in — and demo mode never writes, whatever else is set."""
    if _demo_mode():
        return False
    return _ALLOW_WRITES_FLAG or _env_on("SBER_MCP_ALLOW_WRITES")

def _file_state(path: Path) -> str:
    try:
        _validate_private_source(path, str(path))
        return "present"
    except InsecureSessionFile:
        return "insecure_permissions"
    except MissingSession:
        return "missing"

def _configured_profiles(reg: Registry) -> list[str]:
    found = set()
    prof_dir = reg.home / "profiles"
    if prof_dir.is_dir():
        for p in prof_dir.glob("*.json"):
            if PROFILE.fullmatch(p.stem):
                found.add(p.stem)
    if reg.home.is_dir():
        for c in reg.home.glob("credentials*.json"):
            stem = c.stem.replace("credentials-", "") if c.stem != "credentials" else "default"
            if PROFILE.fullmatch(stem):
                found.add(stem)
    found.update(reg.by_profile)
    return sorted(found) or ["default"]

async def sber_auth_start(mode: str = "auto", profile: str = "default") -> dict:
    reg = _registry()
    if not PROFILE.fullmatch(profile):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "profile"})
    if mode not in ("auto", "cold", "pin", "credentials"):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "mode"})
    existing = reg.by_profile.get(profile)
    if existing is not None and existing.state == "authenticated":
        return ok(_auth_data(existing, reused="live"), session_id=existing.session_id,
                  state="authenticated")
    if len(reg.by_id) >= MAX_SESSIONS and existing is None:
        return err("too_many_sessions", NA_ABORT,
                   details={"closable": list(reg.by_id)})
    cfg = Config(profile=profile, home=reg.home)
    if mode == "auto":
        return await _start_auto(reg, cfg, profile)
    if mode == "cold":
        return await _start_cold(reg, cfg, profile)
    if mode == "pin":
        return await _start_pin(reg, cfg, profile)
    return await _start_credentials(reg, cfg, profile)

def _auth_data(st: SessionState, *, reused: str | None = None) -> dict:
    return {"session_id": st.session_id, "profile": st.profile, "mode": st.mode,
            "reused": reused, "capabilities": _capabilities(st),
            "session": _redacted(st.client.bundle) if st.client else None}

