async def _start_auto(reg: Registry, cfg: Config, profile: str) -> dict:
    path = _profile_path(reg, profile)
    if not path.exists():
        return err("session_file_invalid", NA_REENROLL,
                   details={"hint": "no saved profile; use mode=cold or mode=pin"})
    st = reg._new_state(profile, "auto", "authenticated")
    try:
        client = AsyncSberClient.from_session_file(path)
        await client.warm_up()
        st.client = client
        return ok(_auth_data(st, reused="profile"), session_id=st.session_id, state="authenticated")
    except (MissingSession, AuthenticationExpired):
        # UFS expired — the saved profile is itself the remembered-browser jar.
        st.auth = AsyncPinAuth(SessionBundle.load(path))
        st.mode, st.state, st.client = "pin", "awaiting_pin", None
        return _arm(reg, st, "pin_required", ["pin"])

async def _drive_primary_login(reg: Registry, st: SessionState, login: str, password: str,
                               *, captcha_code: str | None = None) -> dict:
    assert isinstance(st.auth, AsyncPrimaryAuth)
    try:
        try:
            bundle = await st.auth.login(login, password, store_login=True,
                                         captcha_code=captcha_code)
        finally:
            login = password = ""
    except PinOtpRequired as exc:
        return _arm_from_exc(reg, st, exc)
    except PinCaptchaRequired as exc:
        return await _arm_captcha(reg, st, exc)
    return await _finish_or_pinsetup(reg, st, bundle)

async def _finish_or_pinsetup(reg: Registry, st: SessionState, bundle: SessionBundle | None) -> dict:
    if bundle is not None:
        await _enter_authenticated(reg, st, bundle)
        return ok(_auth_data(st), session_id=st.session_id, state="authenticated")
    length = getattr(getattr(st.auth, "_config", None), "pin_length", 5)
    st.state, st.challenge_code = "awaiting_pin_setup", "pin_creation_required"
    st.challenge_expires = _now() + timedelta(minutes=15)
    return _arm(reg, st, "pin_creation_required", ["new_pin", "new_pin_confirm"],
                extra={"pin_length": length})

async def _start_pin(reg: Registry, cfg: Config, profile: str) -> dict:
    cookies = cfg.cookies_export()
    if cookies is None:
        return err("session_file_invalid", NA_REENROLL,
                   details={"hint": "mode=pin needs cookies_export_file for first enrolment"})
    st = reg._new_state(profile, "pin", "awaiting_pin")
    st.auth = AsyncPinAuth.from_browser_cookies(cookies, deviceprint=cfg.deviceprint(),
                                                antifraud_deviceprint=cfg.antifraud())
    return _arm(reg, st, "pin_required", ["pin"])

async def _start_credentials(reg: Registry, cfg: Config, profile: str) -> dict:
    creds = cfg.ufs_credentials()
    if creds is None:
        return err("secret_not_configured", NA_FIX_SECRET, details={"field": "ufs_session/ufs_token"})
    st = reg._new_state(profile, "credentials", "authenticated")
    client = AsyncSberClient.from_credentials(creds, session_path=_profile_path(reg, profile),
                                              antifraud_deviceprint=cfg.antifraud())
    await client.warm_up()
    st.client = client
    return ok(_auth_data(st, reused=None), session_id=st.session_id, state="authenticated")

def _arm(reg: Registry, st: SessionState, code: str, expects: list[str],
         *, extra: dict | None = None) -> dict:
    path = reg.arm_inbox(st, expects)
    st.challenge_code = code
    st.challenge_expires = _now() + timedelta(minutes=15)
    details = {"delivery": {"mode": "file", "path": str(path)}, "expects": expects}
    if st.captcha_artifact is not None:
        details["artifact_path"] = str(st.captcha_artifact)
    if extra:
        details.update(extra)
    return challenge(code, details=details, session_id=st.session_id, state=st.state)

async def sber_auth_continue(session_id: str | None = None, wait_seconds: int = 30,
                             use_audio_captcha: bool = False) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if not st.state.startswith("awaiting_"):
        return err("auth_state_invalid", NA_RESTART, session_id=session_id, state=st.state)
    st.last_activity = _now()
    if st.state == "awaiting_captcha" and use_audio_captcha:
        if st.captcha_challenge is None or st.captcha_challenge.audio_url is None:
            return err("invalid_arguments", NA_FIX_ARGS, session_id=session_id, state=st.state,
                       details={"field": "use_audio_captcha"})
        return await _arm_captcha(reg, st, st.captcha_challenge, audio=True)
    # poll the inbox
    deadline = time.monotonic() + max(0, min(int(wait_seconds), 300))
    while True:
        try:
            lines = reg.read_inbox(st)
        except _InboxReplaced:
            return err("inbox_replaced", NA_SUBMIT, session_id=session_id, state=st.state,
                       details={"delivery": {"mode": "file", "path": str(st.inbox_path)}})
        if lines is not None:
            break
        if time.monotonic() >= deadline:
            return err("inbox_empty", NA_SUBMIT, session_id=session_id, state=st.state,
                       details={"delivery": {"mode": "file", "path": str(st.inbox_path)},
                                "retry_after_seconds": 10})
        await asyncio.sleep(1)
    return await _advance(reg, st, lines)

