async def _advance(reg: Registry, st: SessionState, lines: list[str]) -> dict:
    state = st.state
    assert st.auth is not None
    try:
        if state == "awaiting_pin":
            pin = _one(lines, st)
            try:
                bundle = await st.auth.login(pin)
            finally:
                pin = ""
            return await _finish_pin_result(reg, st, bundle)
        if state == "awaiting_otp":
            code = _one(lines, st)
            try:
                bundle = await st.auth.confirm_otp(code)
            finally:
                code = ""
            return await _finish_or_pinsetup(reg, st, bundle)
        if state == "awaiting_pin_setup":
            if len(lines) < 2 or not hmac.compare_digest(lines[0], lines[1]):
                for i in range(len(lines)):
                    lines[i] = ""
                return _arm(reg, st, "pin_creation_required", ["new_pin", "new_pin_confirm"],
                            extra={"problem": "pin_mismatch"})
            pin = lines[0]
            lines[0] = lines[1] = ""
            assert isinstance(st.auth, AsyncPrimaryAuth)
            try:
                _validate_pin_shape(pin, getattr(getattr(st.auth, "_config", None), "pin_length", 5))
                bundle = await st.auth.create_pin(pin)
            finally:
                pin = ""
            await _enter_authenticated(reg, st, bundle)
            return ok(_auth_data(st), session_id=st.session_id, state="authenticated")
        if state == "awaiting_captcha":
            return await _advance_captcha(reg, st, lines)
    except PinOtpRequired as exc:
        return _arm_from_exc(reg, st, exc)
    except PinCaptchaRequired as exc:
        if st.state == "awaiting_otp":
            await reg.close(st)
            return err("auth_process_reset", NA_RESTART)  # captcha during OTP unsupported (R-6)
        return await _arm_captcha(reg, st, exc)
    return err("auth_state_invalid", NA_RESTART, session_id=st.session_id, state=st.state)

async def _advance_captcha(reg: Registry, st: SessionState, lines: list[str]) -> dict:
    cfg = Config(profile=st.profile, home=reg.home)
    if st.mode == "cold":
        captcha = _one(lines, st)
        login, password = cfg.login_password()
        try:
            return await _drive_primary_login(reg, st, login, password, captcha_code=captcha)
        finally:
            captcha = ""
    pin, captcha = (lines + ["", ""])[0], (lines + ["", ""])[1]
    assert st.auth is not None
    try:
        bundle = await st.auth.login(pin, captcha_code=captcha)
    finally:
        pin = captcha = ""
    return await _finish_pin_result(reg, st, bundle)

async def _finish_pin_result(reg: Registry, st: SessionState, bundle: SessionBundle | None) -> dict:
    if bundle is None:
        return await _finish_or_pinsetup(reg, st, bundle)
    await _enter_authenticated(reg, st, bundle)
    return ok(_auth_data(st), session_id=st.session_id, state="authenticated")

def _one(lines: list[str], st: SessionState) -> str:
    if not lines:
        raise ValueError("empty secret")
    return lines[0]

def _validate_pin_shape(pin: str, length: int) -> None:
    if not isinstance(pin, str) or len(pin) != length or not pin.isascii() or not pin.isdigit():
        raise ValueError(f"PIN must be exactly {length} ASCII digits")

async def sber_auth_resend_otp(session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if st.state != "awaiting_otp":
        return err("auth_state_invalid", NA_RESTART, session_id=session_id, state=st.state)
    st.last_activity = _now()
    assert st.auth is not None
    exc = await st.auth.retry_otp()          # returns PinOtpRequired
    return _arm_from_exc(reg, st, exc)

async def sber_session_info(session_id: str | None = None, check_live: bool = False) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    live = "unknown"
    if check_live and st.client is not None:
        try:
            await st.client.warm_up(force=True)
            live = "ok"
        except AuthenticationExpired:
            return err("session_expired", NA_REAUTH_PIN, session_id=session_id, state=st.state)
    data = {
        "session_id": st.session_id, "profile": st.profile, "state": st.state,
        "capabilities": _capabilities(st), "created_at": _iso(st.created_at),
        "last_activity": _iso(st.last_activity), "live": live,
        "pending": {"challenge": st.challenge_code, "open_drafts": len(st.drafts),
                    "prepared_transfers": len(st.prepared),
                    "unresolved_audit_id": st.unresolved_audit},
        "session": _redacted(st.client.bundle) if st.client else None,
    }
    return ok(data, session_id=session_id, state=st.state)

async def sber_session_close(session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
    except _NotFound:
        return ok({"state": "closed", "discarded": {"challenges": 0, "drafts": 0,
                                                     "prepared_transfers": 0}})
    discarded = await reg.close(st)
    return ok({"state": "closed", "discarded": discarded})

def _need_client(st: SessionState) -> AsyncSberClient:
    if st.client is None or st.state != "authenticated":
        raise _NotFound()
    return st.client

def _parse_date(value: str | None):
    if value is None:
        return None
    return datetime.strptime(value, "%Y-%m-%d").date()

async def sber_operations_page(session_id: str | None = None, resource: str | None = None, offset: int = 0,
                               limit: int = 30, from_date: str | None = None,
                               to_date: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
        client = _need_client(st)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if resource is not None and not OP_RESOURCE.fullmatch(resource):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "resource"})
    limit = max(1, min(int(limit), 50))
    st.last_activity = _now()
    page = await client.operations.page(resource=resource, offset=max(0, int(offset)), limit=limit,
                                        from_=_parse_date(from_date), to=_parse_date(to_date))
    return ok({"count": len(page.operations), "next_offset": page.next_offset,
               "operations": [_operation_out(o) for o in page.operations]},
              session_id=session_id, state="authenticated")

async def sber_card_rename(card_id: str, name: str, session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
        client = _need_client(st)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if not CARD_ID.fullmatch(str(card_id)):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "card_id"})
    if not CARD_NAME.fullmatch(name or ""):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "name"})
    if not _capabilities(st)["mutations"]:
        return err("antifraud_deviceprint_missing", NA_FIX_SECRET)
    if st.unresolved_audit:
        return err("unresolved_uncertain_transfer", NA_UNKNOWN)
    st.last_activity = _now()
    await client.warm_up(force=True)                       # preflight: clean read failure vs uncertain
    audit_id = reg.audit("card_rename", {"card_id": card_id, "name": name}, "in_flight")
    await client.cards.rename(card_id, name)
    reg.audit("card_rename", {"card_id": card_id, "name": name}, "completed")
    return ok({"card_id": card_id, "name": name, "audit_id": audit_id},
              session_id=session_id, state="authenticated")

async def sber_transfer_start(session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
        client = _need_client(st)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if not _capabilities(st)["mutations"]:
        return err("antifraud_deviceprint_missing", NA_FIX_SECRET)
    if st.unresolved_audit:
        return err("unresolved_uncertain_transfer", NA_UNKNOWN)
    st.last_activity = _now()
    await client.warm_up(force=True)
    draft = await client.transfers.start()
    draft_id = "dft_" + secrets.token_hex(16)
    st.drafts[draft_id] = draft
    return ok({"draft_id": draft_id, "expires_at": _iso(_now() + timedelta(seconds=600)),
               "sources": [_transfer_res_out(r) for r in draft.sources],
               "destinations": [_transfer_res_out(r) for r in draft.destinations]},
              session_id=session_id, state="authenticated")

async def sber_transfer_prepare(draft_id: str, source_id: str, destination_id: str,
                                amount: str, currency: str = "RUB", payment_purpose: str = "",
                                session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
        client = _need_client(st)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if st.unresolved_audit:
        return err("unresolved_uncertain_transfer", NA_UNKNOWN)
    draft = st.drafts.get(draft_id)
    if draft is None or not DRAFT_ID.fullmatch(draft_id or ""):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "draft_id"})
    if not TRANSFER_RES.fullmatch(source_id or "") or not TRANSFER_RES.fullmatch(destination_id or ""):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "source_id/destination_id"})
    if not AMOUNT.fullmatch(amount or ""):
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "amount", "constraint": "decimal string > 0"})
    try:
        amount_dec = Decimal(amount)
    except InvalidOperation:
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "amount"})
    st.last_activity = _now()
    prepared = await client.transfers.prepare(draft, source_id=source_id,
                                              destination_id=destination_id, amount=amount_dec,
                                              currency=currency, payment_purpose=payment_purpose)
    token = "cnf_" + secrets.token_hex(16)
    src = next((r for r in draft.sources if r.id == source_id), None)
    dst = next((r for r in draft.destinations if r.id == destination_id), None)
    review = {
        "from": f"{src.name if src else source_id} ({source_id})",
        "to": f"{dst.name if dst else destination_id} ({destination_id})",
        "amount": f"{format(prepared.amount.amount, 'f')} {prepared.amount.currency}",
        "payment_purpose": payment_purpose, "prepared_at": _iso(_now()),
    }
    audit_id = reg.audit("transfer_prepare",
                         {"amount": review["amount"], "source_id": source_id,
                          "destination_id": destination_id, "payment_purpose": payment_purpose},
                         "prepared")
    st.prepared[token] = PreparedRecord(
        token=token, prepared=prepared, review=review, destination_id=destination_id,
        amount_text=review["amount"], audit_id=audit_id,
        expires_at=_now() + timedelta(seconds=300))
    return challenge("transfer_approval_required", next_action=NA_APPROVAL, details={
        "confirmation_token": token, "expires_at": _iso(st.prepared[token].expires_at),
        "review": review,
        "instructions": "Show `review` to the human verbatim. Call sber_transfer_confirm only "
                        "after an explicit yes.",
    }, session_id=session_id, state="authenticated")

async def sber_transfer_confirm(confirmation_token: str, acknowledged_amount: str,
                                acknowledged_destination_id: str,
                                session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
        _need_client(st)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    rec = st.prepared.get(confirmation_token)
    if rec is None or not CONF_TOKEN.fullmatch(confirmation_token or ""):
        return err("unknown_confirmation_token", NA_RESTART)
    if rec.spent:
        # A repeat never starts a second sequence: await the in-flight task or return the outcome.
        if rec.outcome == "in_flight" and rec.task is not None:
            try:
                await asyncio.shield(rec.task)
            except BaseException:
                pass
        return err("transfer_already_attempted", NA_UNKNOWN,
                   details={"recorded_outcome": rec.outcome, "result": rec.result})
    if _now() > rec.expires_at:
        return err("confirmation_token_expired", NA_FIX_ARGS)
    if not hmac.compare_digest(acknowledged_amount or "", rec.amount_text) or \
       not hmac.compare_digest(acknowledged_destination_id or "", rec.destination_id):
        return err("acknowledgement_mismatch", NA_FIX_ARGS)
    if st.unresolved_audit:
        return err("unresolved_uncertain_transfer", NA_UNKNOWN)
    st.last_activity = _now()
    rec.spent, rec.outcome = True, "in_flight"           # BURN FIRST
    reg.audit("transfer_confirm", {"amount": rec.amount_text,
                                   "destination_id": rec.destination_id}, "in_flight")
    assert st.client is not None
    try:
        rec.task = asyncio.ensure_future(st.client.transfers.confirm(rec.prepared))
        result = await asyncio.shield(rec.task)
    except MutationUncertain:
        rec.outcome = "uncertain"
        st.unresolved_audit = rec.audit_id
        reg.audit("transfer_confirm", {"amount": rec.amount_text,
                                       "destination_id": rec.destination_id}, "uncertain")
        env = err("mutation_uncertain", NA_UNKNOWN, details={
            "operation": "transfer_confirm", "phase": "sent_result_unknown",
            "audit_id": rec.audit_id, "verify_with": ["sber_operations", "sber_products"],
            "verify_hint": {"amount": rec.amount_text, "destination_id": rec.destination_id}},
            session_id=session_id, state="authenticated")
        rec.result = env
        return env
    except BaseException as exc:
        rec.outcome = "uncertain"
        st.unresolved_audit = rec.audit_id
        rec.result = map_error(exc)
        return rec.result
    rec.outcome = "completed"
    reg.audit("transfer_confirm", {"amount": rec.amount_text,
                                   "destination_id": rec.destination_id}, "completed",
              document_id=result.document_id)
    data = {"status": "completed", "document_id": result.document_id,
            "amount": _money(rec.prepared.amount), "destination_id": rec.destination_id,
            "audit_id": rec.audit_id, "do_not_retry": True}
    rec.result = ok(data, session_id=session_id, state="authenticated")
    return rec.result

async def sber_transfer_resolve_uncertain(audit_id: str, found: bool,
                                          session_id: str | None = None) -> dict:
    reg = _registry()
    try:
        st = reg.resolve(session_id)
    except _NotFound:
        return err("session_not_found", NA_RESTART)
    session_id = st.session_id
    if st.unresolved_audit != audit_id:
        return err("invalid_arguments", NA_FIX_ARGS, details={"field": "audit_id"})
    st.unresolved_audit = None
    resolved = "applied" if found else "not_applied"
    reg.audit("transfer_resolve", {"audit_id": audit_id}, resolved)
    return ok({"audit_id": audit_id, "resolved_as": resolved, "transfers_unblocked": True},
              session_id=session_id, state="authenticated")

def _guard(fn: Callable[..., Awaitable[dict]]) -> Callable[..., Awaitable[dict]]:
    """One decorator, every tool: no tool ever raises to MCP; per-session serialisation."""
    @functools.wraps(fn)
    async def wrapper(*args: Any, **kwargs: Any) -> dict:
        try:
            return await fn(*args, **kwargs)
        except asyncio.CancelledError:
            raise
        except _NotFound:
            return err("session_not_found", NA_RESTART)
        except _Ambiguous as exc:
            return err("session_ambiguous", NA_FIX_ARGS,
                       details={"active_sessions": exc.session_ids,
                                "hint": "more than one active session; pass session_id"})
        except BaseException as exc:  # noqa: BLE001 — deliberate: envelope, never a raw raise
            return map_error(exc)
    return wrapper

async def wrapper(*args: Any, **kwargs: Any) -> dict:
        try:
            return await fn(*args, **kwargs)
        except asyncio.CancelledError:
            raise
        except _NotFound:
            return err("session_not_found", NA_RESTART)
        except _Ambiguous as exc:
            return err("session_ambiguous", NA_FIX_ARGS,
                       details={"active_sessions": exc.session_ids,
                                "hint": "more than one active session; pass session_id"})
        except BaseException as exc:  # noqa: BLE001 — deliberate: envelope, never a raw raise
            return map_error(exc)

def _build_server():
    try:
        from mcp.server import MCPServer as _Server  # mcp >= 2
    except ImportError:  # pragma: no cover
        from mcp.server.fastmcp import FastMCP as _Server  # mcp 1.x
    instructions = AGENT_INSTRUCTIONS
    if _demo_mode():
        instructions += DEMO_INSTRUCTIONS
    elif not _allow_writes():
        instructions += READ_ONLY_INSTRUCTIONS
    server = _Server("sber-unofficial", instructions=instructions)
    _assert_no_show_locals()
    for fn in _TOOLS:
        # Gate at registration, not inside the tool: an unregistered tool is not
        # in the agent's schema at all, which is a stronger guarantee than any
        # check the model could be argued out of. `_TOOLS` itself stays whole —
        # tools/render_brand.py parses that list to build the README graphics.
        if fn.__name__ in _WRITE_TOOLS and not _allow_writes():
            continue
        if fn.__name__ in _AUTH_TOOLS and _demo_mode():
            continue
        server.tool(name=fn.__name__, description=(fn.__doc__ or fn.__name__).strip())(_guard(fn))
    return server

def _assert_no_show_locals() -> None:
    """Refuse to run under a traceback renderer that captures locals (secrets in frames)."""
    try:
        import rich.traceback as rt
    except ImportError:
        return
    installed = getattr(rt, "_installed_hook", None)
    if installed is not None and getattr(installed, "show_locals", False):  # pragma: no cover
        raise RuntimeError("rich traceback show_locals is on; refuse to expose secret-bearing frames")

def _lang() -> str:
    """Interface language from the system locale (override with SBER_MCP_LANG)."""
    value = (os.environ.get("SBER_MCP_LANG") or os.environ.get("LC_ALL")
             or os.environ.get("LC_MESSAGES") or os.environ.get("LANG") or "").lower()
    if value.startswith("ru"):
        return "ru"
    if value.startswith(("zh", "cn")):
        return "zh"
    return "en"

def _has(module: str) -> bool:
    import importlib.util
    return importlib.util.find_spec(module) is not None

def _grad(t: float, stops: list = _GRADIENT) -> str:
    """Hex colour at position t∈[0,1] along the brand gradient."""
    t = max(0.0, min(1.0, t))
    for (p0, c0), (p1, c1) in zip(stops, stops[1:], strict=False):
        if p0 <= t <= p1:
            k = 0.0 if p1 == p0 else (t - p0) / (p1 - p0)
            r, g, b = (round(c0[i] + (c1[i] - c0[i]) * k) for i in range(3))
            return f"#{r:02x}{g:02x}{b:02x}"
    return SBER_GREEN

def _print_banner() -> None:
    if _has("rich"):
        from rich.console import Console
        from rich.text import Text
        console = Console(highlight=False)
        rows = _SBER_FIGLET.strip("\n").split("\n")
        h = max(1, len(rows) - 1)
        w = max(1, max(len(r) for r in rows) - 1)
        block = Text()
        for y, row in enumerate(rows):                 # per-cell diagonal gradient (blue→yellow)
            for x, ch in enumerate(row):
                if ch == " ":
                    block.append(" ")
                else:
                    block.append(ch, style=f"bold {_grad(0.66 * (y / h) + 0.34 * (x / w))}")
            block.append("\n")
        console.print(block, end="")
        console.print("  unofficial", style=SBER_GREEN)
        console.print()
    else:
        print(_SBER_FIGLET)
        print("  unofficial\n")

async def _ask(prompt: str) -> str:
    if _has("questionary") and _interactive():
        import questionary
        answer = await questionary.text(prompt, style=_q_style(), qmark="◗").ask_async()
        if answer is None:
            raise KeyboardInterrupt
        return answer.strip()
    return input(prompt + " ").strip()

async def _password(prompt: str) -> str:
    if _has("questionary") and _interactive():
        import questionary
        answer = await questionary.password(prompt, style=_q_style(), qmark="◗").ask_async()
        if answer is None:
            raise KeyboardInterrupt
        return answer
    from getpass import getpass
    return getpass(prompt + " ")

async def _confirm(prompt: str, *, default: bool = False) -> bool:
    if _has("questionary") and _interactive():
        import questionary
        answer = await questionary.confirm(
            prompt, default=default, style=_q_style(), qmark="◗").ask_async()
        return bool(answer)
    suffix = "Y/n" if default else "y/N"
    return input(f"{prompt} [{suffix}]: ").strip().lower() in {"y", "yes", "д", "да"}

def _note(message: str, *, kind: str = "info") -> None:
    colors = {"info": SBER_GREEN, "warn": "yellow", "error": "red", "ok": f"bold {SBER_GREEN}"}
    if _has("rich"):
        from rich.console import Console
        Console(highlight=False).print(message, style=colors.get(kind, SBER_GREEN))
    else:
        print(message)

def _server_tty_notice() -> None:
    msg = f"{_t('srv_l1')}\n{_t('srv_l2')}\n{_t('srv_l3')}"
    if _has("rich"):
        from rich.console import Console
        from rich.panel import Panel
        Console(stderr=True).print(Panel.fit(msg, title="sber-mcp", border_style=SBER_GREEN))
    else:
        print(msg, file=sys.stderr)

def _ensure_fingerprint(home: Path, name: str, generator: Callable[[], str]) -> str:
    path = home / name
    if path.exists():
        return _read_secret_file(path)
    value = generator()
    fd = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY
                 | getattr(os, "O_NOFOLLOW", 0), 0o600)
    with os.fdopen(fd, "w", encoding="utf-8") as file:
        file.write(value)
    return value

