async def _cli_otp_loop(auth):
    for _ in range(5):
        code = await _password(_t("p_sms"))
        try:
            return await auth.confirm_otp(code)
        except PinAuthError as error:
            if error.code == "expired_code":
                if await _confirm(_t("q_otp_resend")):
                    await auth.retry_otp()
                    continue
            if error.code == "wrong_code":
                _note(_t("e_wrong_sms"), kind="warn")
                continue
            raise
        finally:
            code = ""
    raise SystemExit(_t("e_too_many_sms"))

def _cli_login(argv: list[str]) -> None:
    profile = "default"
    i = 0
    while i < len(argv):
        if argv[i] == "--profile" and i + 1 < len(argv):
            profile = argv[i + 1]
            i += 2
        else:
            raise SystemExit(f"unknown argument: {argv[i]} (usage: sber-unofficial-mcp login [--profile NAME])")
    if not PROFILE.fullmatch(profile):
        raise SystemExit("--profile must match [a-z0-9_-]{1,32}")
    _print_banner()
    home = _home()
    home.mkdir(parents=True, exist_ok=True)
    os.chmod(home, 0o700)
    deviceprint = _ensure_fingerprint(home, DEVICEPRINT_FILE, _generate_deviceprint)
    antifraud = _ensure_fingerprint(home, ANTIFRAUD_FILE, _generate_antifraud)
    try:
        path = asyncio.run(_run_login(home, profile, deviceprint, antifraud))
    except PinAuthError as error:
        raise SystemExit(_t("login_failed", code=error.code or "error")) from None
    except (SberError, OSError) as error:
        raise SystemExit(_t("login_failed", code=type(error).__name__)) from None
    except (KeyboardInterrupt, EOFError):
        raise SystemExit(_t("cancelled")) from None
    _note(_t("saved", path=path), kind="ok")

def _status_mark(state: str) -> tuple[str, str]:
    return {
        "present": (_t("v_present"), SBER_GREEN),
        "configured": (_t("v_present"), SBER_GREEN),
        "missing": (_t("v_missing"), "red"),
        "insecure_permissions": (_t("v_insecure"), "yellow"),
    }.get(state, (state, "white"))

def main() -> None:
    global _ALLOW_WRITES_FLAG, _DEMO_FLAG
    argv = sys.argv[1:]
    if argv and argv[0] in ("login", "setup", "enroll"):
        _cli_login(argv[1:])
        return
    if argv and argv[0] == "status":
        _cli_status(argv[1:])
        return
    if argv and argv[0] in ("serve", "run"):
        argv = argv[1:]
    if "--allow-writes" in argv:
        _ALLOW_WRITES_FLAG = True
        argv = [a for a in argv if a != "--allow-writes"]
    if "--demo" in argv:
        _DEMO_FLAG = True
        argv = [a for a in argv if a != "--demo"]
    try:
        server = _build_server()
    except ImportError as error:
        raise SystemExit("MCP support is not installed. Run: pip install sber-unofficial-mcp") from error
    if sys.stdin.isatty():
        _server_tty_notice()      # to stderr — stdout is the JSON-RPC channel
    server.run("stdio")

def __init__(self, seed: SessionSeed, session: SessionLike | None = None):
        if not _online_url(seed.api_base) or not _online_url(seed.web_base):
            raise ValueError("разрешены только HTTPS-хосты online.sberbank.ru")
        self.seed = seed
        self._session = session or _make_session(seed)
        self._last_warmup = clock.monotonic()

def _post(self, base: str, path: str, payload: Mapping[str, Any]) -> Mapping[str, Any]:
        if path not in READ_PATHS and path != WARMUP_PATH:
            raise ValueError(f"endpoint не входит в read-only allowlist: {path}")
        if path in READ_PATHS and clock.monotonic() - self._last_warmup >= WARMUP_DEBOUNCE_SECONDS:
            self.warm_up()
        response = self._session.post(
            f"{base.rstrip('/')}{path}",
            json=dict(payload),
            accept_encoding="gzip, deflate, br, zstd",
        )
        if response.status_code in (301, 302, 303, 307, 308, 401, 403):
            raise AuthenticationExpired("сессия СберБанк Онлайн истекла или отклонена")
        if path == WARMUP_PATH and response.status_code in (200, 204):
            content_type = next(
                (str(value).lower() for name, value in response.headers.items() if str(name).lower() == "content-type"),
                "",
            )
            if "text/html" in content_type:
                raise AuthenticationExpired("warmUpSession вернул страницу входа")
            return {}
        if response.status_code != 200:
            raise ApiError(f"Сбер вернул HTTP {response.status_code}")
        try:
            data = response.json()
        except Exception as error:
            raise AuthenticationExpired("вместо JSON получен ответ страницы входа") from error
        if not isinstance(data, Mapping):
            raise ApiError("ожидался JSON object")
        success = data.get("success")
        if path != WARMUP_PATH and not (success is True or success == "true"):
            code = data.get("error", {}).get("code") if isinstance(data.get("error"), Mapping) else None
            raise ApiError(f"API success=false{f', code={code}' if code else ''}")
        return data

def warm_up(self) -> None:
        self._post(self.seed.web_base, WARMUP_PATH, {})
        self._last_warmup = clock.monotonic()

def products(self, *, force_update: bool = False) -> tuple[list[Account], list[Card]]:
        payload = self._post(
            self.seed.api_base,
            PRODUCTS_PATH,
            {"withData": True, "forceUpdate": bool(force_update)},
        )
        return parse_products(payload)

def operations_page(
        self,
        *,
        resource: str | None = None,
        offset: int = 0,
        limit: int = 30,
        from_: date | datetime | None = None,
        to: date | datetime | None = None,
    ) -> OperationsPage:
        if resource is not None and not RESOURCE.fullmatch(resource):
            raise ValueError(
                "resource должен иметь вид card:<id>, ct-account:<id> или account:<id>"
            )
        if offset < 0 or not 1 <= limit <= 100:
            raise ValueError("offset >= 0, limit от 1 до 100")
        if from_ and to and _request_moment(from_) > _request_moment(to, end=True):
            raise ValueError("from_ должен быть не позже to")

        if from_ is None and to is None:
            from_ = _default_from()

        body: dict[str, Any] = {
            "paginationOffset": offset,
            "paginationSize": limit + 1,
            "showHidden": False,
            "showNotTransactionBonuses": True,
            "showOpenBanking": True,
        }
        if from_:
            body["from"] = _request_datetime(from_)
        if to:
            body["to"] = _request_datetime(to, end=True)
        if resource:
            body["usedResource"] = [resource]

        payload = self._post(self.seed.api_base, OPERATIONS_PATH, body)
        operations = parse_operations(payload, [resource] if resource else [])
        if any(not operation.id for operation in operations):
            raise ApiError("операция без обязательного uohId; история не может быть собрана без потерь")
        has_next = len(operations) > limit
        return OperationsPage(
            operations=operations[:limit],
            next_offset=offset + limit if has_next else None,
        )

def operations(
        self,
        *,
        resource: str | None = None,
        limit: int = 30,
        from_: date | datetime | None = None,
        to: date | datetime | None = None,
        max_pages: int = 100,
    ) -> list[Operation]:
        by_id: dict[str, Operation] = {}
        offset = 0
        if from_ is None and to is None:
            from_ = _default_from()
        for _ in range(max_pages):
            page = self.operations_page(
                resource=resource,
                offset=offset,
                limit=limit,
                from_=from_,
                to=to,
            )
            for operation in page.operations:
                if operation.id:
                    by_id[operation.id] = operation
            if page.next_offset is None:
                return sorted(by_id.values(), key=lambda item: item.date, reverse=True)
            offset = page.next_offset
        raise ApiError(f"достигнут защитный предел max_pages={max_pages}")

