def private_directory(path):
    path = Path(path)
    if path.is_symlink() or (path.exists() and not path.is_dir()):
        raise PermissionError("Небезопасный путь приватного состояния")
    path.mkdir(mode=0o700, parents=True, exist_ok=True)
    metadata = path.stat()
    if metadata.st_uid != os.getuid() or stat.S_IMODE(metadata.st_mode) != 0o700:
        raise PermissionError("Приватный каталог должен принадлежать пользователю и иметь права 0700")
    return path

def make_auth(ca_bundle):
    ca_bundle = Path(ca_bundle).resolve(strict=True)
    if not ca_bundle.is_file():
        raise ValueError("Нет локального CA bundle")
    # Browser NSS trust and curl PEM trust are separate and application-scoped.
    try:
        from sber_unofficial import FirefoxBrowserBootstrap
    except ImportError:
        raise PinAuthError("Установленный SDK не содержит optional browser bootstrap", code="browser_bootstrap_unavailable") from None
    bootstrap = FirefoxBrowserBootstrap(BASE / "private/browser-ca-profile", timeout=45)
    deviceprint = generate_deviceprint()
    return AsyncPrimaryAuth.new(
        deviceprint=deviceprint,
        antifraud_deviceprint=generate_antifraud_deviceprint(deviceprint),
        ca_bundle=ca_bundle,
        browser_bootstrap=bootstrap,
        browser_bootstrap_timeout=55,
    )

def hidden_prompt(prompt, label):
    """Reject getpass's echoed fallback before it can consume any input."""
    with warnings.catch_warnings():
        warnings.simplefilter("error", GetPassWarning)
        try:
            return prompt(label)
        except GetPassWarning:
            raise PermissionError("Терминал не поддерживает безопасный скрытый ввод") from None

def main(argv=None):
    parser = argparse.ArgumentParser(description="Локальный ex3lite SDK: без MCP и платёжных команд")
    parser.add_argument("command", choices=("status", "doctor", "login"))
    args = parser.parse_args(argv)
    if args.command == "login" and not (sys.stdin.isatty() and sys.stderr.isatty()):
        print("Нужен интерактивный терминал сервера (SSH). Не передавайте секреты через чат, аргументы или pipe.", file=sys.stderr)
        return 2
    profile = BASE / "private/profile.json"
    if args.command == "status":
        print(json.dumps({"sdk_version": __version__, "profile_exists": profile.is_file(), "bank_authorization_checked": False}, ensure_ascii=False))
        return 0

    async def run_selected_flow():
        if args.command == "login":
            private_directory(BASE / "private")
        async with make_auth(BASE / "certs/application-ca-bundle.pem") as auth:
            if args.command == "login":
                await authorize(auth, profile, prompt=getpass)
            else:
                await auth._load_primary_config()

    facts: dict[str, str | bool] = {"sdk_version": __version__, "stage": "authorization" if args.command == "login" else "unauthenticated_bootstrap"}
    if args.command == "doctor":
        facts["bank_login_attempted"] = False
    try:
        asyncio.run(run_selected_flow())
        facts["ready"] = True
    except PinAuthError as error:
        public_codes = {
            "invalid_frontend_config", "bootstrap_failed", "browser_check_required",
            "browser_bootstrap_timeout", "browser_bootstrap_unavailable",
            "browser_bootstrap_failed", "browser_owner_required",
            "unsupported_browser_state", "unsafe_bootstrap_request",
        }
        facts.update(ready=False, error=error.code if error.code in public_codes else "bootstrap_failed")
    except Exception as error:
        facts.update(ready=False, error=type(error).__name__)
    print(json.dumps(facts, ensure_ascii=False))
    return 0 if facts["ready"] else 3

