def test_cookie_domain_leading_dot_is_canonicalized(tmp_path):
    path = tmp_path / "replace.har"
    entries = []
    for index, (domain, value) in enumerate((
        (".online.sberbank.ru", "old"),
        ("online.sberbank.ru", "new"),
    )):
        entries.append({
            "startedDateTime": f"2026-07-13T09:0{index}:00Z",
            "request": {
                "method": "POST",
                "url": f"https://web-node2.online.sberbank.ru{PRODUCTS_PATH}",
                "headers": [],
            },
            "response": {
                "headers": [{
                    "name": "Set-Cookie",
                    "value": f"SID={value}; Domain={domain}; Path=/; Secure",
                }],
                "content": {},
            },
        })
    write_har(path, entries)
    inspection, jar = inspect_har(path)
    cookies = list(jar)
    assert inspection.cookie_count == 1
    assert cookies[0].domain == "online.sberbank.ru"
    assert cookies[0].value == "new"

def test_operations_freezes_default_from_between_pages(monkeypatch):
    first = {
        "success": True,
        "body": {"operations": [
            {"uohId": "1", "state": {}},
            {"uohId": "sentinel", "state": {}},
        ]},
    }
    second = {
        "success": True,
        "body": {"operations": [{"uohId": "2", "state": {}}]},
    }
    fake = FakeSession([FakeResponse(first), FakeResponse(second)])
    seed = SessionSeed(
        "https://web-node2.online.sberbank.ru",
        "https://web2.online.sberbank.ru",
        cookies=None,  # type: ignore[arg-type]
        observed_headers={},
    )
    calls = 0

    def moving_default():
        nonlocal calls
        calls += 1
        return datetime(2026, 3, 1, 12, 0, calls)

    monkeypatch.setattr(sber_client_module, "_default_from", moving_default)
    result = SberClient(seed, session=fake).operations(limit=1)
    assert {operation.id for operation in result} == {"1", "2"}
    assert calls == 1
    assert fake.calls[0][1]["json"]["from"] == fake.calls[1][1]["json"]["from"]

